body.script:
//
                (function () {
                    var CSRF = document.body.getAttribute('data-csrf') || '';
                    var BASE = '/machine_repair/mobile';
                    // App 内原生扫码桥（系统相机 + 本地 ZXing 解码），比 WebView 摄像头稳得多
                    var NATIVE = (typeof window.AndroidScanner !== 'undefined') ? window.AndroidScanner : null;
                    window.onNativeScan = function (text) { if (text) { onDecoded(text); } };
                    // 原生拍照返回：拍完直接上传（不用再点确认）
                    window.onNativePhoto = function (kind, dataUrl) {
                        if (!currentQr) { toast('请先扫码或生成二维码'); return; }
                        if (!dataUrl) { return; }
                        var qrId = currentQr.id;
                        toast('照片已拍，正在上传…');
                        uploadPhoto(qrId, kind || 'front', dataUrl).then(function (res) {
                            if (!res.ok) { toast(res.error || '上传失败'); return; }
                            toast('已上传' + ({front: '正面', back: '反面', detail: '局部'}[kind] || ''));
                            // 先用接口返回的数据立即刷新（不依赖第二次请求）
                            if (currentQr && res.photo_list) {
                                currentQr.photo_list = res.photo_list;
                                currentQr.photos = {
                                    front: res.front, back: res.back,
                                    detail: res.photo_list.filter(function (p) { return p.kind === 'detail'; }).length
                                };
                                currentQr.has_photos = res.has_photos;
                                renderQr(currentQr);
                            }
                            var code = lastCode || (currentQr && currentQr.name);
                            if (code) {
                                post('/scan', {code: code}).then(function (r2) {
                                    if (r2.ok && r2.qr) { renderQr(r2.qr); }
                                }).catch(function () { });
                            }
                        }).catch(function () { toast('网络不稳，照片没传上去'); });
                    };
                    window.onNativeScanSn = function (text) {
                        if (!text) { return; }
                        document.getElementById('newqr-sn').value = text;
                        toast('已扫到条码：' + text);
                    };
                    var video = document.getElementById('video');
                    var canvas = document.createElement('canvas');
                    var stream = null, raf = null, lastCode = null, pickedPartner = null;
                    var currentQr = null;          // 当前板件（扫码或新建）
                    var pendingKind = null;        // 本次要拍的部位
                    var zxReader = null, scanMode = 'qr', scanning = false, frames = 0, ctx2d = null;
                    var urgency = 'normal';
                    var newQr = null;
                    // 发货：勾选的待发货工单 / 本次拍的包装照片 / 扫快递单后是否回到发货页
                    var shipPicked = {}, shipPhotos = [], shipScanReturn = false;
                    // 保修月数下拉只在“换了一块板”时重置，避免拍完照片刷新界面把用户的选择冲掉
                    var warrantyQrId = null;
                    var QUEUE_KEY = 'mr_queue_v1';
                    var PHOTO_KEY = 'mr_photos_v1';
                    var STATE_CLASS = {
                        '待抢单': 'warn', '维修中': 'info', '超时接力': 'bad',
                        '已完工': 'ok', '接力完工': 'ok', '已退单': 'muted', '新建': 'muted', '已确认': 'info'
                    };

                    function toast(msg, ms) {
                        var t = document.getElementById('toast');
                        t.textContent = msg; t.className = 'show';
                        clearTimeout(window.__tt);
                        window.__tt = setTimeout(function () { t.className = ''; }, ms || 3000);
                        // 详情页里也顺手写一份状态，免得提示被键盘/浮层挡住看不到
                        var hint = document.getElementById('d-hint');
                        if (hint && document.getElementById('order-detail').style.display === 'block') {
                            hint.textContent = msg;
                        }
                    }
                    // 同时用于文本内容和 HTML 属性：引号也必须转义，
                    // 否则视频文件名里带 " 会把 data-xxx 属性截断（点击就没反应）。
                    function esc(s) {
                        return String(s === undefined || s === null ? '' : s)
                            .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
                            .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
                    }
                    var escAttr = esc;
                    function post(path, data, isForm) {
                        var body;
                        if (isForm) { body = data; }
                        else {
                            body = new URLSearchParams();
                            body.append('csrf_token', CSRF);
                            Object.keys(data || {}).forEach(function (k) { body.append(k, data[k]); });
                        }
                        return fetch(BASE + path, {
                            method: 'POST', credentials: 'same-origin',
                            headers: isForm ? {} : {'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8'},
                            body: body
                        }).then(function (r) { return r.json(); });
                    }

                    // ---------------- 离线队列 ----------------
                    function getJSON(key) { try { return JSON.parse(localStorage.getItem(key) || '[]'); } catch (e) { return []; } }
                    function setJSON(key, v) { localStorage.setItem(key, JSON.stringify(v)); updateBadge(); }
                    function updateBadge() {
                        var n = getJSON(QUEUE_KEY).length + getJSON(PHOTO_KEY).length;
                        var online = navigator.onLine;

                        var b = document.getElementById('queue-badge');
                        if (b) {
                            b.style.display = n ? 'inline-block' : 'none';
                            b.textContent = '待上传 ' + n;
                        }
                        // + 号圆块：
                        //   有待上传 -> 显示数字 + 琥珀色 + 呼吸更快
                        //   离线     -> 变灰、停止呼吸
                        //   都恢复   -> 自动变回 + 号
                        var btn = document.getElementById('btn-quick-scan');
                        if (btn) {
                            btn.textContent = n ? (n > 99 ? '99+' : String(n)) : '＋';
                            if (n > 0) { btn.classList.add('has-pending'); }
                            else { btn.classList.remove('has-pending'); }
                            if (online) { btn.classList.remove('offline'); }
                            else { btn.classList.add('offline'); }
                            btn.setAttribute('title', n ? ('待上传 ' + n) : '扫码');
                        }
                        var net = document.getElementById('net');
                        if (net) { net.textContent = online ? '在线' : '离线'; }
                    }
                    function queued(path, data, label) {
                        return post(path, data).catch(function () {
                            var q = getJSON(QUEUE_KEY);
                            q.push({path: path, data: data, label: label, at: Date.now()});
                            setJSON(QUEUE_KEY, q);
                            return {ok: false, queued: true};
                        });
                    }
                    function flushQueue() {
                        var q = getJSON(QUEUE_KEY);
                        if (!q.length) { flushPhotos(); return; }
                        var item = q[0];
                        post(item.path, item.data).then(function (res) {
                            q.shift(); setJSON(QUEUE_KEY, q);
                            toast(res && res.error ? ('补传失败：' + res.error) : ('已补传：' + (item.label || '')));
                            if (q.length) { setTimeout(flushQueue, 400); } else { flushPhotos(); }
                        }).catch(function () { });
                    }
                    function flushPhotos() {
                        var q = getJSON(PHOTO_KEY);
                        if (!q.length) { updateBadge(); return; }
                        var item = q[0];
                        var fd = new FormData();
                        fd.append('csrf_token', CSRF);
                        fd.append('qr_id', item.qr_id);
                        fd.append('kind', item.kind);
                        fd.append('photo', dataURLtoBlob(item.data), 'photo.jpg');
                        fetch(BASE + '/photo', {method: 'POST', credentials: 'same-origin', body: fd})
                            .then(function (r) { return r.json(); })
                            .then(function (res) {
                                if (res && (res.ok || res.error)) {
                                    q.shift(); setJSON(PHOTO_KEY, q);
                                    toast(res.ok ? '照片已补传' : ('照片补传失败：' + res.error));
                                    if (q.length) { setTimeout(flushPhotos, 400); }
                                }
                            }).catch(function () { });
                    }
                    function dataURLtoBlob(dataURL) {
                        var parts = dataURL.split(','), mime = parts[0].match(/:(.*?);/)[1];
                        var bin = atob(parts[1]), arr = new Uint8Array(bin.length);
                        for (var i = 0; i < bin.length; i++) { arr[i] = bin.charCodeAt(i); }
                        return new Blob([arr], {type: mime});
                    }

                    // ---------------- 摄像头（ZXing：二维码 + 一维码 + 快递单 Code128） ----------------
                    function stopCamera() {
                        scanning = false;
                        if (raf) { clearTimeout(raf); raf = null; }
                        if (stream) { stream.getTracks().forEach(function (t) { t.stop(); }); stream = null; }
                        video.srcObject = null;
                        document.getElementById('scan-box').style.display = 'none';
                        document.getElementById('btn-start').style.display = 'block';
                        document.getElementById('btn-stop').style.display = 'none';
                    }
                    function buildHints() {
                        if (!window.ZXing) { return null; }
                        var hints = new Map();
                        hints.set(ZXing.DecodeHintType.TRY_HARDER, true);
                        hints.set(ZXing.DecodeHintType.POSSIBLE_FORMATS, [
                            ZXing.BarcodeFormat.QR_CODE,
                            ZXing.BarcodeFormat.CODE_128,
                            ZXing.BarcodeFormat.CODE_39,
                            ZXing.BarcodeFormat.CODE_93,
                            ZXing.BarcodeFormat.CODABAR,
                            ZXing.BarcodeFormat.EAN_13,
                            ZXing.BarcodeFormat.EAN_8,
                            ZXing.BarcodeFormat.UPC_A,
                            ZXing.BarcodeFormat.UPC_E,
                            ZXing.BarcodeFormat.ITF,
                            ZXing.BarcodeFormat.DATA_MATRIX,
                            ZXing.BarcodeFormat.PDF_417,
                            ZXing.BarcodeFormat.AZTEC
                        ]);
                        return hints;
                    }
                    function onDecoded(text) {
                        if (!text) { return; }
                        var mode = scanMode;
                        stopCamera();
                        scanMode = 'qr';
                        if (mode === 'sn') {
                            document.getElementById('newqr-sn').value = text;
                            toast('已扫到条码：' + text);
                            return;
                        }
                        if (mode === 'track') {
                            // 扫快递单：写回发货页的「快递单号」，再回到发货页
                            var input = document.getElementById('ship-tracking');
                            if (input) { input.value = text; }
                            toast('已扫到快递单号：' + text);
                            if (shipScanReturn) {
                                shipScanReturn = false;
                                switchView('msg');
                                switchMsgTab('ship');
                                document.getElementById('ship-sheet').style.display = 'block';
                            }
                            return;
                        }
                        handleCode(text);
                    }
                    function startCamera(mode) {
                        scanMode = mode || 'qr';
                        if (scanning) { return; }
                        if (/MicroMessenger|QQ\/|Weibo|AlipayClient/i.test(navigator.userAgent)) {
                            document.getElementById('cam-hint').innerHTML =
                                '<b style="color:#c0392b">微信/QQ 内置浏览器禁止摄像头</b>，请用系统浏览器或本 App 打开。';
                            return;
                        }
                        if (!window.isSecureContext) { toast('必须用 https:// 打开'); return; }
                        if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
                            toast('这台手机不支持摄像头'); return;
                        }
                        var box = document.getElementById('scan-box');
                        box.style.display = 'block';
                        video.style.display = 'block';
                        document.getElementById('scan-hud').textContent = '正在打开摄像头…';
                        document.getElementById('btn-start').style.display = 'none';
                        document.getElementById('btn-stop').style.display = 'block';
                        // 看门狗：2.5 秒还没有画面，说明取流失败（权限/占用/WebView 限制）
                        clearTimeout(window.__camWatch);
                        window.__camWatch = setTimeout(function () {
                            if (!video.videoWidth) {
                                document.getElementById('scan-hud').textContent =
                                    '⚠ 没有拿到画面（vid0）—— 检查摄像头权限后重试';
                            }
                        }, 2500);

                        // ZXing 只负责"解码"（本地、离线）；取流和循环由我们自己控制，
                        // 这样能显示扫描线、帧计数，并且失败也不影响继续扫描。
                        if (!zxReader && window.ZXing) {
                            try { zxReader = new ZXing.BrowserMultiFormatReader(buildHints()); }
                            catch (e) { zxReader = null; }
                        }
                        if (!window.ZXing) {
                            document.getElementById('cam-hint').innerHTML =
                                '<b style="color:#c0392b">⚠ ZXing 本地库没加载成功</b>（只退回二维码识别）。' +
                                '请检查网络后彻底关掉 App 重开；仍不行告我。';
                        }

                        navigator.mediaDevices.getUserMedia({
                            video: {facingMode: {ideal: 'environment'},
                                    width: {ideal: 1920}, height: {ideal: 1080}},
                            audio: false
                        }).then(function (s) {
                            stream = s;
                            video.srcObject = s;
                            video.setAttribute('playsinline', 'true');
                            return video.play();
                        }).then(function () {
                            scanning = true;
                            frames = 0;
                            clearTimeout(window.__camWatch);
                            document.getElementById('scan-hud').textContent =
                                '正在扫描… ' + (video.videoWidth || 0) + '×' + (video.videoHeight || 0);
                            scanLoop();
                        }).catch(function (err) {
                            var name = (err && err.name) ? err.name : 'UnknownError';
                            document.getElementById('cam-hint').innerHTML =
                                '<b style="color:#c0392b">摄像头打不开：' + name + '</b>（' +
                                ({NotAllowedError: '授权被拒绝，去设置里允许摄像头',
                                  NotFoundError: '没有摄像头', NotReadableError: '摄像头被其它应用占用',
                                  SecurityError: '安全策略禁止'}[name] || '未知原因') + '）';
                            stopCamera();
                        });
                    }
                    function scanLoop() {
                        if (!scanning) { return; }
                        try {
                            if (video.readyState >= 2 && video.videoWidth) {
                                if (!ctx2d) { ctx2d = canvas.getContext('2d', {willReadFrequently: true}); }
                                var vw = video.videoWidth, vh = video.videoHeight;
                                // 一维码（快递单）对水平分辨率敏感，尽量不缩放
                                var scale = Math.min(1, 1920 / (vw || 1920));
                                canvas.width = Math.round(vw * scale);
                                canvas.height = Math.round(vh * scale);
                                ctx2d.drawImage(video, 0, 0, canvas.width, canvas.height);
                                frames += 1;
                                var text = decodeFrame(ctx2d);
                                if (frames % 3 === 0) {
                                    document.getElementById('scan-hud').textContent =
                                        '正在扫描… 第 ' + frames + ' 帧 · ' + vw + '×' + vh +
                                        '（' + (window.ZXing ? 'ZXing 本地解码' : '仅二维码模式') +
                                        '）';
                                }
                                if (text) { onDecoded(text); return; }
                            }
                        } catch (e) { }
                        raf = setTimeout(scanLoop, 150);
                    }
                    function decodeFrame(ctx) {
                        // 1) ZXing：二维码 + 一维码（快递单 Code128 等）
                        if (zxReader) {
                            try {
                                var result = zxReader.decodeFromCanvas(canvas);
                                if (result && result.getText()) { return result.getText(); }
                            } catch (e) { /* 没扫到就是常态，继续下一帧 */ }
                        }
                        // 2) 退路：jsQR 只认二维码（部分老 WebView 没有 ZXing）
                        if (!zxReader && window.jsQR) {
                            try {
                                var img = ctx.getImageData(0, 0, canvas.width, canvas.height);
                                var found = window.jsQR(img.data, img.width, img.height,
                                                        {inversionAttempts: 'attemptBoth'});
                                if (found && found.data) { return found.data; }
                            } catch (e) { }
                        }
                        return null;
                    }

                    // ---------------- 板件信息 ----------------
                    function kv(label, value) {
                        return '<div class="kv"><span>' + label + '</span><b>' + esc(value || '-') + '</b></div>';
                    }
                    function stateTag(state) {
                        var cls = STATE_CLASS[state] || 'muted';
                        return '<span class="tag ' + cls + '">' + esc(state) + '</span>';
                    }
                    function renderQr(q) {
                        currentQr = q;
                        var html = '';
                        html += kv('二维码', q.name);
                        html += kv('客户', q.customer);
                        if (q.customer_type_label) { html += kv('客户类型', q.customer_type_label); }
                        html += kv('机台', q.machine);
                        html += kv('板件型号', q.product);
                        html += kv('包月', (q.monthly_start || '-') + ' ~ ' + (q.monthly_end || '-'));
                        html += '<div class="kv"><span>保修</span><b>' +
                                '<span class="tag ' + (q.in_warranty ? 'ok' : 'bad') + '">' +
                                esc(q.warranty_state) + '</span> ' + esc(q.warranty_end || '') + '</b></div>';
                        html += kv('已维修次数', q.repair_count);
                        // 活期客户：可以改本次保修月数（首次维修从发货快递时间起算）
                        var wBox = document.getElementById('warranty-box');
                        if (wBox) {
                            var isAdhoc = q.customer_type === 'adhoc';
                            wBox.style.display = isAdhoc ? 'block' : 'none';
                            if (isAdhoc && String(warrantyQrId) !== String(q.id)) {
                                var sel = document.getElementById('warranty-months');
                                if (sel && q.warranty_months) {
                                    sel.value = String(q.warranty_months);
                                }
                                warrantyQrId = q.id;
                            }
                        }
                        if (!q.machine || !q.product) {
                            html += '<div class="hint" style="color:#c0392b;margin-top:6px">' +
                                '这张码还没有' + (!q.machine ? '机台' : '') +
                                (!q.machine && !q.product ? ' / ' : '') +
                                (!q.product ? '板件型号' : '') +
                                '档案：先照常建单，建好后在「详情 → 补填机台 / 板件」里补上即可。</div>';
                        }
                        document.getElementById('qr-kv').innerHTML = html;

                        var photos = q.photos || {front: 0, back: 0, detail: 0};
                        var photoList = q.photo_list || [];
                        var kindLabel = {front: '正面', back: '反面', detail: '局部'};
                        var thumbHtml = '';
                        if (photoList.length) {
                            // 已上传的照片按类型分组，直接显示缩略图（点击看大图）
                            ['front', 'back', 'detail'].forEach(function (kind) {
                                var group = photoList.filter(function (p) { return p.kind === kind; });
                                if (!group.length) { return; }
                                thumbHtml += '<div style="width:100%;margin-top:6px">' +
                                    '<span class="tag ' + (kind === 'detail' ? 'info' : 'ok') + '">' +
                                    kindLabel[kind] + ' ' + group.length + '</span>' +
                                    '<div class="thumbs">' + group.map(function (p) {
                                        var big = (window.location.origin + p.url).replace('image_256', 'image_1024');
                                        var small = window.location.origin + p.url + '?v=' + p.id;
                                        return '<a href="' + big + '" target="_blank">' +
                                            '<img src="' + small + '" ' +
                                            'onerror="this.style.display=\'none\'; this.nextSibling.style.display=\'block\';"/>' +
                                            '<span style="display:none;font-size:11px;color:#c0392b">加载失败</span></a>';
                                    }).join('') + '</div></div>';
                            });
                        }
                        document.getElementById('thumbs').innerHTML =
                            '<span class="tag ' + (photos.front ? 'ok' : 'bad') + '">正面 ' + photos.front + '</span>' +
                            '<span class="tag ' + (photos.back ? 'ok' : 'bad') + '">反面 ' + photos.back + '</span>' +
                            '<span class="tag info">局部 ' + photos.detail + '</span>' + thumbHtml;

                        var hist = q.history || [];
                        document.getElementById('history-box').innerHTML = hist.length
                            ? '<div class="hint">维修履历：</div>' + hist.map(function (h) {
                                return '<div class="history-item">' + esc(h.date) + ' · ' + esc(h.name) +
                                    ' · ' + stateTag(h.state) +
                                    (h.technician ? ' · ' + esc(h.technician) : '') +
                                    (h.fault ? ' · ' + esc(h.fault) : '') + '</div>';
                            }).join('')
                            : '<div class="hint">还没有维修记录（首次维修）</div>';

                        // 未完成工单：可直接抢单 / 接力
                        var openOrders = q.orders || [];
                        var claimHtml = '';
                        if (openOrders.length) {
                            claimHtml += '<div class="hint" style="margin-top:8px">这块板有未完成的工单，可直接抢单或完工：</div>';
                            openOrders.forEach(function (o) {
                                claimHtml += '<div class="order"><div class="info"><b>' + esc(o.name) +
                                    '</b> ' + stateTag(o.state) + '<br/>' + esc(o.urgency) +
                                    ' · 期限 ' + esc(o.deadline) +
                                    (o.technician ? ' · ' + esc(o.technician) : '') + '</div><div class="row">' +
                                    (o.claimable
                                        ? '<button class="btn small" data-claim="' + o.id + '">' +
                                          (o.state_key === 'timeout_alert' ? '接力抢单' : '抢单') + '</button>'
                                        : '') +
                                    '<button class="btn small ok" data-complete="' + o.id + '">完工</button>' +
                                    '</div></div>';
                            });
                        }
                        document.getElementById('claim-box').innerHTML = claimHtml;

                        // 一周内刚完工：只提醒，不拦截
                        var warn = document.getElementById('repeat-warn');
                        if (q.recent_done) {
                            warn.style.display = 'block';
                            warn.innerHTML = '⚠ 这块板 <b>' + esc(q.recent_done.date) + '</b> 刚完工（单号 ' +
                                esc(q.recent_done.order) +
                                (q.recent_done.technician ? '，师傅 ' + esc(q.recent_done.technician) : '') +
                                '），距今 <b>' + q.recent_done.days + ' 天</b>。<br/>' +
                                '如果器件还没交付/寄回，就不必再开单；确实需要重开，请继续操作。';
                        } else {
                            warn.style.display = 'none';
                        }

                        document.getElementById('photo-block').style.display =
                            q.has_photos ? 'none' : 'block';
                        document.getElementById('result').style.display = 'block';
                        document.getElementById('result').scrollIntoView({behavior: 'smooth'});
                    }
                    function handleCode(code) {
                        lastCode = code;
                        post('/scan', {code: code}).then(function (res) {
                            if (res.ok) { renderQr(res.qr); return; }
                            document.getElementById('result').style.display = 'none';
                            currentQr = null;
                            if (res.switch_to_new) {
                                // 不是本系统的码（快递单/商品条码/原厂码）→ 切到「生码建单」
                                lastCode = null;
                                switchTab('new');
                                document.getElementById('newqr-sn').value = res.code || '';
                                toast(res.hint || '不是本系统的码：请先生成二维码');
                                var card = document.getElementById('newqr-card');
                                card.scrollIntoView({behavior: 'smooth'});
                                document.getElementById('newqr-q').focus();
                                return;
                            }
                            toast(res.hint || res.error || '没有找到这张码');
                        });
                    }

                    // ---------------- 拍照 ----------------
                    function compressImage(file) {
                        return new Promise(function (resolve) {
                            var img = new Image();
                            var url = URL.createObjectURL(file);
                            img.onload = function () {
                                var max = 1600, w = img.width, h = img.height;
                                if (w > max || h > max) {
                                    var ratio = Math.min(max / w, max / h);
                                    w = Math.round(w * ratio); h = Math.round(h * ratio);
                                }
                                var c = document.createElement('canvas');
                                c.width = w; c.height = h;
                                c.getContext('2d').drawImage(img, 0, 0, w, h);
                                URL.revokeObjectURL(url);
                                resolve(c.toDataURL('image/jpeg', 0.78));
                            };
                            img.onerror = function () { resolve(null); };
                            img.src = url;
                        });
                    }
                    function uploadPhoto(qrId, kind, dataUrl) {
                        var fd = new FormData();
                        fd.append('csrf_token', CSRF);
                        fd.append('qr_id', qrId);
                        fd.append('kind', kind);
                        fd.append('photo', dataURLtoBlob(dataUrl), 'photo.jpg');
                        return fetch(BASE + '/photo', {method: 'POST', credentials: 'same-origin', body: fd})
                            .then(function (r) { return r.json(); });
                    }

                    // ---------------- 工单（分栏菜单） ----------------
                    var ordersData = {groups: {}, counts: {}};
                    var taskTab = 'pending';
                    var mineTab = 'repairing';
                    var TASK_TABS = [['pending', '待抢单'], ['repairing', '维修中'],
                                     ['timeout', '超时接力'], ['done', '已完工']];
                    var MINE_TABS = [['repairing', '维修中'], ['timeout', '超时接力'],
                                     ['done', '已完工']];

                    function orderRow(o) {
                        var isDone = (o.state_key === 'done' || o.state_key === 'secondary_completed');
                        var html = '<div class="order" data-detail="' + o.id + '"><div class="info"><b>' + esc(o.name) + '</b> ' +
                            stateTag(o.state) + '<br/>' +
                            esc(o.urgency) + ' · ' + esc(o.machine || '-') +
                            (o.partner ? ' · ' + esc(o.partner) : '') +
                            '<br/>期限 ' + esc(o.deadline || '-') +
                            (o.overdue ? ' <span class="tag bad">超期</span>' : '') +
                            (o.invoiced ? ' <span class="tag ok">已开票</span>' : '') +
                            (isDone
                                ? (o.shipped
                                    ? ' <span class="tag ok">已发货 ' + esc(o.tracking_no || '') + '</span>'
                                    : ' <span class="tag warn">未发货</span>')
                                : '') +
                            (o.has_photos ? '' : ' <span class="tag warn">缺正反面照片</span>') +
                            '</div><div class="row">' +
                            '<button class="btn small ghost" data-detail="' + o.id + '">详情</button>';
                        // 抢单只对「大厅里没人接」的单子有意义；完工/开票只对自己抢到的单子出现
                        if (o.claimable) {
                            html += '<button class="btn small" data-claim="' + o.id + '">抢单</button>';
                        }
                        if (o.mine && o.can_complete) {
                            html += '<button class="btn small ok" data-complete="' + o.id + '">完工</button>';
                        }
                        if (o.mine && window.__canInvoice && !o.invoiced &&
                            (o.state_key === 'done' || o.state_key === 'secondary_completed')) {
                            html += '<button class="btn small" data-invoice="' + o.id + '">开票</button>';
                        }
                        html += '</div></div>';
                        return html;
                    }

                    function renderTabs(barId, tabs, activeKey, scope) {
                        var bar = document.getElementById(barId);
                        if (!bar) { return; }
                        bar.innerHTML = tabs.map(function (tab) {
                            var key = tab[0];
                            var countKey = (scope === 'mine') ? ('mine_' + key) : key;
                            var n = (ordersData.counts || {})[countKey] || 0;
                            return '<button class="tab' + (key === activeKey ? ' active' : '') +
                                '" data-' + scope + '-tab="' + key + '">' + tab[1] +
                                (n ? ' <b>' + n + '</b>' : '') + '</button>';
                        }).join('');
                    }

                    function renderOrderList(boxId, bucket, emptyText) {
                        var box = document.getElementById(boxId);
                        if (!box) { return; }
                        var list = (ordersData.groups || {})[bucket] || [];
                        box.innerHTML = list.length
                            ? list.map(orderRow).join('')
                            : '<div class="empty">' + emptyText + '</div>';
                    }

                    function renderTask() {
                        renderTabs('task-tabs', TASK_TABS, taskTab, 'task');
                        renderOrderList('task-list', taskTab,
                            taskTab === 'pending' ? '大厅里暂时没有待抢的工单'
                                                   : '这个分栏里暂时没有工单');
                    }

                    function renderMine() {
                        renderTabs('mine-tabs', MINE_TABS, mineTab, 'mine');
                        renderOrderList('mine-list', 'mine_' + mineTab, '这个分栏里暂时没有工单');
                    }

                    function onOrderTabClick(ev) {
                        var el = ev.target;
                        while (el && el !== this) {
                            if (el.getAttribute) {
                                var t = el.getAttribute('data-task-tab');
                                if (t) { taskTab = t; renderTask(); return; }
                                t = el.getAttribute('data-mine-tab');
                                if (t) { mineTab = t; renderMine(); return; }
                            }
                            el = el.parentNode;
                        }
                    }

                    function loadOrders() {
                        post('/my_orders', {}).then(function (res) {
                            if (!res.ok) { toast(res.error || '读不到工单'); return; }
                            window.__canInvoice = !!res.can_invoice;
                            ordersData = {groups: res.groups || {}, counts: res.counts || {}};
                            renderTask();
                            renderMine();
                            renderMsgGroups();
                            updateBadge();
                        }).catch(function () { toast('当前离线'); updateBadge(); });
                    }

                    // ---------------- 消息 → 开票 / 发货 ----------------
                    function renderMsgGroups() {
                        renderInvoiceList();
                        renderShipList();
                    }

                    function doneRowInfo(o) {
                        return '<div class="info"><b>' + esc(o.name) + '</b> ' + stateTag(o.state) +
                            '<br/>' + esc(o.machine || '-') +
                            (o.partner ? ' · ' + esc(o.partner) : '') +
                            (o.tracking_no ? '<br/>快递单号：' + esc(o.tracking_no) : '') +
                            '</div>';
                    }

                    function renderInvoiceList() {
                        var box = document.getElementById('invoice-list');
                        if (!box) { return; }
                        var list = (ordersData.groups || {}).invoice || [];
                        var counter = document.getElementById('invoice-count');
                        var total = (ordersData.counts || {}).invoice || 0;
                        if (counter) { counter.textContent = total ? total : ''; }
                        if (!list.length) {
                            box.innerHTML = '<div class="empty">没有待开票的工单</div>';
                            return;
                        }
                        box.innerHTML = list.map(function (o) {
                            var html = '<div class="order">' + doneRowInfo(o) + '<div class="row">' +
                                '<button class="btn small ghost" data-detail="' + o.id + '">详情</button>';
                            if (window.__canInvoice && !o.invoiced) {
                                html += '<button class="btn small" data-invoice="' + o.id + '">开票</button>';
                            } else if (!window.__canInvoice) {
                                html += '<span class="tag muted">开票要会计/管理员</span>';
                            }
                            return html + '</div></div>';
                        }).join('');
                    }

                    function renderShipList() {
                        var box = document.getElementById('ship-list');
                        if (!box) { return; }
                        var list = (ordersData.groups || {}).ship || [];
                        var counter = document.getElementById('ship-count');
                        var total = (ordersData.counts || {}).ship || 0;
                        if (counter) { counter.textContent = total ? total : ''; }
                        if (!list.length) {
                            shipPicked = {};
                            box.innerHTML = '<div class="empty">没有待发货的工单</div>';
                            updateShipButton();
                            return;
                        }
                        // 已经不在待发货列表里的勾选要清掉（可能刚发完货）
                        var alive = {};
                        list.forEach(function (o) { alive[o.id] = true; });
                        Object.keys(shipPicked).forEach(function (id) {
                            if (!alive[id]) { delete shipPicked[id]; }
                        });
                        box.innerHTML = list.map(function (o) {
                            var checked = shipPicked[o.id] ? ' checked="checked"' : '';
                            return '<div class="order"><div class="info">' +
                                '<label style="display:flex;gap:8px;align-items:flex-start;margin:0">' +
                                '<input type="checkbox" data-ship-pick="' + o.id + '"' + checked +
                                ' style="width:22px;height:22px;margin-top:2px;flex:none"/>' +
                                '<span><b>' + esc(o.name) + '</b> ' + stateTag(o.state) + '<br/>' +
                                esc(o.machine || '-') + (o.partner ? ' · ' + esc(o.partner) : '') +
                                (o.warranty_pending
                                    ? '<br/><span class="tag info">保修待发货起算</span>' : '') +
                                '</span></label></div><div class="row">' +
                                '<button class="btn small ghost" data-detail="' + o.id + '">详情</button>' +
                                '</div></div>';
                        }).join('');
                        updateShipButton();
                    }

                    function updateShipButton() {
                        var n = Object.keys(shipPicked).length;
                        var btn = document.getElementById('btn-ship-open');
                        if (btn) {
                            btn.textContent = '合并发货（已选 ' + n + '）';
                            btn.disabled = (n === 0);
                        }
                    }

                    function openShipSheet() {
                        var ids = Object.keys(shipPicked);
                        if (!ids.length) { toast('先勾选要发货的工单'); return; }
                        var list = ids.map(function (id) { return shipPicked[id]; });
                        document.getElementById('ship-sel-list').innerHTML = list.map(function (o) {
                            return '<div class="order">' + doneRowInfo(o) + '</div>';
                        }).join('');
                        shipPhotos = [];
                        renderShipThumbs();
                        document.getElementById('ship-tracking').value = '';
                        document.getElementById('ship-carrier').value = '';
                        document.getElementById('ship-sheet').style.display = 'block';
                        document.getElementById('ship-hint').textContent = '';
                        window.scrollTo(0, 0);
                    }

                    function renderShipThumbs() {
                        var box = document.getElementById('ship-thumbs');
                        if (!box) { return; }
                        box.innerHTML = shipPhotos.length
                            ? shipPhotos.map(function (src, index) {
                                return '<div style="position:relative;margin:0 6px 6px 0">' +
                                    '<img src="' + src + '" style="width:74px;height:74px;' +
                                    'object-fit:cover;border-radius:8px;border:1px solid #e6dff2"/>' +
                                    '<button class="btn small danger" data-shipphoto-del="' + index +
                                    '" style="position:absolute;top:-6px;right:-6px;width:24px;height:24px;' +
                                    'padding:0;border-radius:12px;font-size:12px;line-height:1">×</button>' +
                                    '</div>';
                            }).join('')
                            : '<div class="empty">还没有照片（至少 1 张）</div>';
                    }

                    function addShipPhotos(files) {
                        var list = Array.prototype.slice.call(files || []);
                        if (!list.length) { return; }
                        var left = list.length;
                        list.forEach(function (file) {
                            compressImage(file).then(function (dataUrl) {
                                if (dataUrl) { shipPhotos.push(dataUrl); }
                                left -= 1;
                                if (left === 0) {
                                    renderShipThumbs();
                                    toast('已添加包装照片 ' + shipPhotos.length + ' 张');
                                }
                            });
                        });
                    }

                    function submitShip() {
                        var ids = Object.keys(shipPicked);
                        if (!ids.length) { toast('先勾选要发货的工单'); return; }
                        var tracking = document.getElementById('ship-tracking').value.trim();
                        if (!tracking) { toast('请先扫或填快递单号'); return; }
                        if (!shipPhotos.length) { toast('请先拍照上传包装照片（至少 1 张）'); return; }
                        var btn = document.getElementById('btn-ship-confirm');
                        btn.disabled = true;
                        btn.textContent = '正在发货…';
                        var fd = new FormData();
                        fd.append('csrf_token', CSRF);
                        fd.append('order_ids', ids.join(','));
                        fd.append('tracking_no', tracking);
                        var carrier = document.getElementById('ship-carrier').value.trim();
                        if (carrier) { fd.append('carrier', carrier); }
                        shipPhotos.forEach(function (dataUrl, index) {
                            fd.append('photo', dataURLtoBlob(dataUrl), 'pack-' + (index + 1) + '.jpg');
                        });
                        fetch(BASE + '/ship_confirm', {
                            method: 'POST', credentials: 'same-origin', body: fd
                        }).then(function (r) { return r.json(); }).then(function (res) {
                            btn.disabled = false;
                            btn.textContent = '确定发货';
                            if (!res.ok) { toast(res.error || '发货失败'); return; }
                            toast('已发货：' + res.shipment + ' / 快递单号 ' + res.tracking_no +
                                  '（' + res.count + ' 张工单）');
                            shipPicked = {};
                            shipPhotos = [];
                            document.getElementById('ship-sheet').style.display = 'none';
                            loadOrders();
                        }).catch(function () {
                            btn.disabled = false;
                            btn.textContent = '确定发货';
                            toast('网络不稳，发货没提交成功，请重试');
                        });
                    }

                    function scanTracking() {
                        if (NATIVE && NATIVE.scan) {
                            scanMode = 'track';
                            NATIVE.scan();
                            return;
                        }
                        // 浏览器：临时借扫码页的摄像头，扫到后自动回到发货页
                        scanMode = 'track';
                        shipScanReturn = true;
                        document.getElementById('ship-sheet').style.display = 'none';
                        switchView('wo');
                        switchTab('scan');
                        startCamera('qr');
                        toast('对准快递单条码…');
                    }

                    // ---------------- 新建二维码 ----------------
                    function searchNewQrCustomers() {
                        var q = document.getElementById('newqr-q').value.trim();
                        post('/customers', {q: q}).then(function (res) {
                            var box = document.getElementById('newqr-customers');
                            if (!res.ok || !res.customers.length) {
                                box.innerHTML = '<div class="empty">没找到客户</div>'; return;
                            }
                            box.innerHTML = '';
                            res.customers.forEach(function (c) {
                                box.innerHTML += '<button class="btn ghost" data-newcust="' + c.id +
                                    '" style="margin-bottom:6px">' + esc(c.name) + '</button>';
                            });
                        });
                    }
                    function createQr() {
                        if (!pickedPartner) { toast('先选客户'); return; }
                        var sn = document.getElementById('newqr-sn').value.trim();
                        var machineSel = document.getElementById('newqr-machine');
                        var productSel = document.getElementById('newqr-product');
                        post('/new_qr', {
                            partner_id: pickedPartner,
                            sn: sn,
                            machine_id: machineSel ? machineSel.value : '',
                            product_id: productSel ? productSel.value : ''
                        }).then(function (res) {
                            if (!res.ok) { toast(res.error || '生成失败'); return; }
                            toast('已生成 ' + res.qr.name);
                            newQr = res.qr;
                            lastCode = res.qr.name;
                            document.getElementById('newqr-actions').style.display = 'flex';
                            document.getElementById('newqr-result').innerHTML =
                                (res.qr.qr_image
                                    ? '<img src="data:image/png;base64,' + res.qr.qr_image +
                                      '" style="width:160px;height:160px;border:1px solid #eee;border-radius:8px"/>'
                                    : '') +
                                '<div class="hint">编号：<b>' + esc(res.qr.name) + '</b>（已建好，接下来拍照 → 开工单）</div>';
                            renderQr(res.qr);
                        });
                    }
                    var createInFlight = false;
                    function setConfirmBusy(busy) {
                        var btn = document.getElementById('btn-confirm-order');
                        if (!btn) { return; }
                        btn.disabled = busy;
                        btn.textContent = busy ? '建单中…' : '确定建单';
                    }
                    function createOrder(urgency) {
                        // 防连点：以前没有这道锁，车间里手快点两下会真的开出两张单
                        // （日志里 11:51:10 / 11:51:11 两条 create_order）。
                        if (createInFlight) { toast('正在建单，请稍候…'); return; }
                        if (!lastCode) { toast('先扫码或生成二维码'); return; }
                        createInFlight = true;
                        setConfirmBusy(true);
                        var done = function () { createInFlight = false; setConfirmBusy(false); };
                        var payload = {code: lastCode, urgency: urgency};
                        if (pickedPartner) { payload.partner_id = pickedPartner; }
                        if (currentQr && currentQr.id) { payload.qr_id = currentQr.id; }
                        // 机台/板件型号：扫到的板件档案优先，其次用生码建单页当前选择
                        if (currentQr && currentQr.machine_id) { payload.machine_id = currentQr.machine_id; }
                        if (currentQr && currentQr.product_id) { payload.product_id = currentQr.product_id; }
                        var mSel = document.getElementById('newqr-machine');
                        var pSel = document.getElementById('newqr-product');
                        if (!payload.machine_id && mSel && mSel.value) { payload.machine_id = mSel.value; }
                        if (!payload.product_id && pSel && pSel.value) { payload.product_id = pSel.value; }
                        // 活期客户：带上「本次保修月数」（首次维修的保修从发货快递时间起算）
                        if (currentQr && currentQr.customer_type === 'adhoc') {
                            var monthsSel = document.getElementById('warranty-months');
                            if (monthsSel && monthsSel.value) {
                                payload.warranty_months = monthsSel.value;
                            }
                        }
                        // 两个分栏都有输入框，哪个有值用哪个（之前只读扫码页，导致生码建单填的不保存）
                        var pick = function (a, b) {
                            var ea = document.getElementById(a), eb = document.getElementById(b);
                            var va = ea && ea.value ? ea.value.trim() : '';
                            var vb = eb && eb.value ? eb.value.trim() : '';
                            return va || vb;
                        };
                        var saved = {};
                        try { saved = JSON.parse(localStorage.getItem('mr_form_v1') || '{}'); } catch (e) { }
                        var errVal = pick('err-code', 'new-qr-err') || (saved.err || '');
                        var faultVal = pick('fault-desc', 'new-qr-fault') || (saved.fault || '');
                        if (errVal) { payload.error_code = errVal; }
                        if (faultVal) { payload.fault = faultVal; }
                        queued('/create_order', payload, '开单').then(function (res) {
                            done();
                            if (res.queued) { toast('网络不稳，已存本地'); return; }
                            if (res.need_photos) {
                                document.getElementById('photo-block').style.display = 'block';
                                toast('请先拍正反面照片');
                                return;
                            }
                            if (res.need_customer) {
                                toast('库里没有这张码：先在"新板"里生成二维码');
                                return;
                            }
                            if (!res.ok) { toast(res.error || '建单失败'); return; }
                            toast('已开单：' + res.order_name);
                            // 补写一次错误代码/故障（防止建单时没带上）
                            if (res.order_id && (payload.error_code || payload.fault)) {
                                post('/save_work', {order_id: res.order_id,
                                    error_code: payload.error_code || '',
                                    fault: payload.fault || ''}).catch(function () { });
                            }
                            // 重置界面，避免误以为没建成功
                            currentQr = null; lastCode = null; newQr = null;
                            document.getElementById('result').style.display = 'none';
                            ['err-code', 'fault-desc', 'new-qr-err', 'new-qr-fault', 'newqr-sn', 'manual'].forEach(function (id) {
                                var e = document.getElementById(id); if (e) { e.value = ''; }
                            });
                            document.getElementById('newqr-result').innerHTML = '';
                            document.getElementById('newqr-actions').style.display = 'none';
                            document.getElementById('newqr-customers').innerHTML = '';
                            try { localStorage.removeItem('mr_form_v1'); } catch (e) { }
                            switchTab('new');
                            loadOrders();
                        });
                    }
                    function completeOrder(id) {
                        askConfirm('确认已修好并提交完工？', function () { doComplete(id); });
                    }
                    function doComplete(id) {
                        queued('/complete', {order_id: id}, '完工').then(function (res) {
                            if (res.queued) { toast('已存本地，恢复后补传'); return; }
                            if (!res.ok) { toast(res.error || '完工失败'); return; }
                            toast('已完工：' + res.order_name);
                            loadOrders();
                        });
                    }
                    function invoiceOrder(id) {
                        askConfirm('确认开票？', function () { doInvoice(id); });
                    }
                    function doInvoice(id) {
                        queued('/invoice', {order_id: id}, '开票').then(function (res) {
                            if (res.queued) { toast('已存本地，恢复后补传'); return; }
                            if (!res.ok) { toast(res.error || '开票失败'); return; }
                            toast('已开票：' + res.invoice + ' / ' + res.amount);
                            loadOrders();
                        });
                    }

                    // ---------------- 事件 ----------------
                    function switchTab(which) {
                        document.querySelectorAll('.tab').forEach(function (tab) {
                            if (tab.getAttribute('data-tab') === which) { tab.classList.add('active'); }
                            else { tab.classList.remove('active'); }
                        });
                        document.getElementById('panel-task').style.display =
                            (which === 'task') ? 'block' : 'none';
                        document.getElementById('panel-scan').style.display =
                            (which === 'scan') ? 'block' : 'none';
                        document.getElementById('panel-new').style.display =
                            (which === 'new') ? 'block' : 'none';
                        // 板件信息卡只属于扫码/生码；回到扫码页时若仍有当前板件则恢复显示
                        if (which === 'task') {
                            document.getElementById('result').style.display = 'none';
                        } else if (which === 'scan' && currentQr) {
                            document.getElementById('result').style.display = 'block';
                        }
                        if (which !== 'scan') { stopCamera(); }
                        if (which === 'task') { loadOrders(); }
                        // 双保险：面板若因任何原因仍不可见，强制显示
                        var current = document.getElementById('panel-' + which);
                        if (current && current.style.display === 'none') {
                            current.style.display = 'block';
                        }
                    }
                    document.querySelectorAll('.tab').forEach(function (tab) {
                        tab.addEventListener('click', function () { switchTab(tab.getAttribute('data-tab')); });
                    });
                    document.getElementById('btn-start').addEventListener('click', function () {
                        if (NATIVE) { NATIVE.scan(); return; }
                        startCamera('qr');
                    });
                    document.getElementById('btn-stop').addEventListener('click', stopCamera);
                    document.getElementById('btn-scan-sn').addEventListener('click', function () {
                        if (NATIVE) { NATIVE.scanSn(); return; }
                        startCamera('sn');
                        document.getElementById('video').scrollIntoView({behavior: 'smooth'});
                    });
                    // 粘贴：读取剪贴板内容填进输入框（需要用户手势 + https）
                    document.getElementById('btn-paste').addEventListener('click', function () {
                        var input = document.getElementById('manual');
                        if (navigator.clipboard && navigator.clipboard.readText) {
                            navigator.clipboard.readText().then(function (txt) {
                                txt = (txt || '').trim();
                                if (txt) { input.value = txt; toast('已粘贴'); }
                                else { toast('剪贴板是空的'); }
                            }).catch(function () {
                                toast('没有剪贴板权限：请长按输入框手动粘贴');
                                input.focus();
                            });
                        } else {
                            toast('这台手机不支持一键粘贴：请长按输入框手动粘贴');
                            input.focus();
                        }
                    });
                    document.getElementById('btn-manual').addEventListener('click', function () {
                        var v = document.getElementById('manual').value.trim();
                        if (v) { handleCode(v); }
                    });
                    document.getElementById('btn-refresh').addEventListener('click', loadOrders);
                    // 分栏是动态渲染的，点击用事件委托（重新渲染后按钮会换掉）
                    document.getElementById('task-tabs').addEventListener('click', onOrderTabClick);
                    document.getElementById('mine-tabs').addEventListener('click', onOrderTabClick);
                    document.getElementById('btn-new-qr').addEventListener('click', createQr);

                    // 选客户 -> 加载该客户的机台
                    function loadMachines() {
                        var sel = document.getElementById('newqr-machine');
                        var prodSel = document.getElementById('newqr-product');
                        if (!sel) { return; }
                        sel.innerHTML = '<option value="">（选择机台）</option>';
                        if (prodSel) { prodSel.innerHTML = '<option value="">（先选机台）</option>'; }
                        if (!pickedPartner) { return; }
                        post('/machines', {partner_id: pickedPartner}).then(function (res) {
                            if (!res.ok) { return; }
                            if (!res.machines.length) {
                                sel.innerHTML = '<option value="">（该客户还没有机台）</option>';
                                return;
                            }
                            sel.innerHTML = '<option value="">（选择机台）</option>' +
                                res.machines.map(function (m) {
                                    return '<option value="' + m.id + '">' + esc(m.no) +
                                        (m.model ? ' · ' + esc(m.model) : '') + '</option>';
                                }).join('');
                        });
                    }

                    // 选机台 -> 加载板件型号（机型专属排最前）
                    function loadBoards() {
                        var sel = document.getElementById('newqr-product');
                        var mSel = document.getElementById('newqr-machine');
                        if (!sel) { return; }
                        sel.innerHTML = '<option value="">（加载中…）</option>';
                        post('/boards', {machine_id: mSel ? mSel.value : ''}).then(function (res) {
                            if (!res.ok || !res.boards.length) {
                                sel.innerHTML = '<option value="">（还没有电路板产品）</option>';
                                return;
                            }
                            var head = '';
                            var modelBoards = res.boards.filter(function (b) { return b.is_model; });
                            var otherBoards = res.boards.filter(function (b) { return !b.is_model; });
                            if (modelBoards.length) {
                                head += '<optgroup label="★ 本机型专属电路板">' +
                                    modelBoards.map(function (b) {
                                        return '<option value="' + b.id + '">★ ' + esc(b.name) + '</option>';
                                    }).join('') + '</optgroup>';
                            }
                            if (otherBoards.length) {
                                head += '<optgroup label="其它电路板">' +
                                    otherBoards.map(function (b) {
                                        return '<option value="' + b.id + '">' + esc(b.name) + '</option>';
                                    }).join('') + '</optgroup>';
                            }
                            sel.innerHTML = '<option value="">（选择板件型号）</option>' + head;
                        });
                    }
                    document.getElementById('newqr-machine').addEventListener('change', loadBoards);
                    document.getElementById('newqr-q').addEventListener('input', function () {
                        clearTimeout(window.__nq);
                        window.__nq = setTimeout(searchNewQrCustomers, 350);
                    });
                    // 紧急度只是"选择"，真正建单由下面的「确定建单」按钮触发
                    document.querySelectorAll('[data-urgency]').forEach(function (b) {
                        b.addEventListener('click', function () {
                            urgency = b.getAttribute('data-urgency');
                            document.querySelectorAll('[data-urgency]').forEach(function (x) {
                                if (x === b) { x.classList.add('sel'); x.classList.remove('ghost'); }
                                else { x.classList.remove('sel'); x.classList.add('ghost'); }
                            });
                            toast('已选：' + b.textContent);
                        });
                    });
                    // 确定建单
                    document.getElementById('btn-confirm-order').addEventListener('click', function () {
                        if (!currentQr) { toast('请先扫码'); return; }
                        if (!currentQr.has_photos) {
                            document.getElementById('photo-block').style.display = 'block';
                            toast('请先拍正反面照片，再确定建单');
                            return;
                        }
                        createOrder(urgency);
                    });
                    // 取消：清掉当前板件，不建单
                    document.getElementById('btn-cancel-order').addEventListener('click', function () {
                        currentQr = null;
                        lastCode = null;
                        document.getElementById('result').style.display = 'none';
                        document.getElementById('qr-kv').innerHTML = '';
                        document.getElementById('photo-block').style.display = 'none';
                        toast('已取消');
                    });
                    // 新板：确定 → 采用这张码，切到扫码建单页继续拍照/建单
                    document.getElementById('btn-newqr-ok').addEventListener('click', function () {
                        if (!newQr) { toast('请先生成二维码'); return; }
                        lastCode = newQr.name;
                        switchTab('scan');
                        renderQr(newQr);
                        toast('已采用 ' + newQr.name + '，请拍正反面后确定建单');
                    });
                    // 新板：取消 → 放弃这张码（还没照片/工单就删掉，避免垃圾数据）
                    document.getElementById('btn-newqr-cancel').addEventListener('click', function () {
                        if (!newQr) { toast('还没有生成二维码'); return; }
                        var qrId = newQr.id;
                        post('/discard_qr', {qr_id: qrId}).then(function (res) {
                            if (!res.ok) { toast(res.error || '取消失败'); return; }
                            newQr = null;
                            document.getElementById('newqr-result').innerHTML = '';
                            document.getElementById('newqr-actions').style.display = 'none';
                            toast('已放弃这张码');
                        });
                    });
                    document.getElementById('photo-input').addEventListener('change', function (ev) {
                        var file = ev.target.files && ev.target.files[0];
                        ev.target.value = '';
                        if (!file || !currentQr || !pendingKind) { return; }
                        var kind = pendingKind, qrId = currentQr.id;
                        pendingKind = null;
                        compressImage(file).then(function (dataUrl) {
                            if (!dataUrl) { toast('图片处理失败'); return; }
                            uploadPhoto(qrId, kind, dataUrl).then(function (res) {
                                if (!res.ok) { toast(res.error || '上传失败'); return; }
                                toast('已上传' + ({front: '正面', back: '反面', detail: '局部'}[kind] || ''));
                                // 关键：以服务器为准刷新（原来只改本地字段，会出现"照片传了却提示缺正反面"）
                                var code = lastCode || (currentQr && currentQr.name);
                                if (code) {
                                    post('/scan', {code: code}).then(function (r2) {
                                        if (r2.ok && r2.qr) { renderQr(r2.qr); }
                                    });
                                } else {
                                    currentQr.has_photos = res.has_photos;
                                    renderQr(currentQr);
                                }
                            }).catch(function () {
                                var q = getJSON(PHOTO_KEY);
                                q.push({qr_id: qrId, kind: kind, data: dataUrl, at: Date.now()});
                                setJSON(PHOTO_KEY, q);
                                toast('网络不稳，照片已存本地，恢复后自动上传');
                            });
                        });
                    });
                    document.addEventListener('click', function (ev) {
                        var el = ev.target;
                        if (!el || !el.getAttribute) { return; }
                        var v;
                        if ((v = el.getAttribute('data-photo-kind'))) {
                            if (!currentQr) { toast('先扫码'); return; }
                            pendingKind = v;
                            if (NATIVE && NATIVE.takePhoto) {
                                NATIVE.takePhoto(v);          // App 内原生拍照：一步到位
                            } else {
                                document.getElementById('photo-input').click();   // 浏览器退路
                            }
                            return;
                        }
                        if ((v = el.getAttribute('data-newcust'))) {
                            pickedPartner = v;
                            var nameText = el.textContent;
                            var qEl = document.getElementById('newqr-q');
                            if (qEl) { qEl.value = ''; qEl.placeholder = '已选客户：' + nameText + '（点此重新搜索）'; }
                            var listEl = document.getElementById('newqr-customers');
                            if (listEl) { listEl.innerHTML = '<div class="hint" style="color:#1e7b45">✓ 已选：' + nameText + '</div>'; }
                            document.getElementById('btn-new-qr').disabled = false;
                            loadMachines();
                            toast('已选客户：' + nameText);
                            return;
                        }
                        if ((v = el.getAttribute('data-claim'))) {
                            askConfirm('确定要抢这张工单吗？\n抢单后请按时完成，超时会转给其他人接力。', function () {
                                post('/claim', {order_id: v}).then(function (res) {
                                    if (!res.ok) { toast(res.error || '抢单失败'); return; }
                                    toast('已抢到 ' + res.order_name); loadOrders();
                                });
                            });
                            return;
                        }
                        if ((v = el.getAttribute('data-detail'))) {
                            openOrder(v); return;
                        }
                        if ((v = el.getAttribute('data-complete'))) { completeOrder(v); return; }
                        if ((v = el.getAttribute('data-invoice'))) { invoiceOrder(v); return; }
                    });
                    window.addEventListener('online', function () {
                        updateBadge(); toast('网络已恢复，开始补传'); flushQueue();
                    });
                    window.addEventListener('offline', function () {
                        updateBadge(); toast('当前离线，操作先存本地');
                    });
                    if ('serviceWorker' in navigator) {
                        navigator.serviceWorker.register('/machine_repair/mobile/sw.js',
                            {scope: '/machine_repair/mobile/'}).catch(function () { });
                    }
                    // ---------------- 底部导航 ----------------
                    function switchView(name) {
                        ['wo', 'msg', 'case', 'me'].forEach(function (v) {
                            var el = document.getElementById('view-' + v);
                            if (el) { el.style.display = (v === name) ? 'block' : 'none'; }
                        });
                        document.querySelectorAll('.bottomnav [data-view]').forEach(function (b) {
                            if (b.getAttribute('data-view') === name) { b.classList.add('active'); }
                            else { b.classList.remove('active'); }
                        });
                        var header = document.getElementById('app-header');
                        if (header) { header.style.display = (name === 'me') ? 'block' : 'none'; }
                        if (name !== 'wo') { stopCamera(); }
                        if (name === 'msg') { loadTimeline(); }
                        if (name === 'case') { loadCases(); }
                        if (name === 'me') { loadOrders(); }
                        window.scrollTo(0, 0);
                    }
                    document.querySelectorAll('.bottomnav [data-view]').forEach(function (b) {
                        b.addEventListener('click', function () {
                            switchView(b.getAttribute('data-view'));
                        });
                    });
                    document.getElementById('btn-quick-scan').addEventListener('click', function () {
                        switchView('wo');
                        switchTab('scan');
                        if (NATIVE) { NATIVE.scan(); } else { startCamera('qr'); }
                    });
                    // 兜底：确保任何时候至少有一个面板可见
                    function ensureVisiblePanel() {
                        var visible = ['task', 'scan', 'new'].some(function (key) {
                            var el = document.getElementById('panel-' + key);
                            return el && el.style.display !== 'none';
                        });
                        if (!visible) { switchTab('scan'); }
                    }
                    // 不再依赖 HTML 默认值：打开即强制回到「工单 → 扫码建单」
                    try { switchView('wo'); switchTab('scan'); } catch (e) { }
                    ensureVisiblePanel();
                    // 从后台恢复/后退缓存恢复时，再断言一次，避免空白
                    window.addEventListener('pageshow', function (ev) {
                        if (ev.persisted) {
                            try { switchView('wo'); switchTab('scan'); } catch (e) { }
                            ensureVisiblePanel(); loadOrders();
                        }
                    });
                    document.addEventListener('visibilitychange', function () {
                        if (!document.hidden) { ensureVisiblePanel(); }
                    });

                    // 错误代码/故障：输入即保存到本地，避免界面刷新或切换分栏后丢失
                    ['err-code', 'new-qr-err', 'fault-desc', 'new-qr-fault'].forEach(function (id) {
                        var el = document.getElementById(id);
                        if (!el) { return; }
                        el.addEventListener('input', function () {
                            var saved = {};
                            try { saved = JSON.parse(localStorage.getItem('mr_form_v1') || '{}'); } catch (e) { }
                            if (id.indexOf('err') >= 0) { saved.err = el.value; } else { saved.fault = el.value; }
                            localStorage.setItem('mr_form_v1', JSON.stringify(saved));
                        });
                    });
                    // 照片灯箱：页内放大 + 关闭
                    document.addEventListener('click', function (ev) {
                        var el = ev.target;
                        if (el && el.getAttribute && el.getAttribute('data-photo-view')) {
                            document.getElementById('photo-viewer-img').src = el.getAttribute('data-photo-view');
                            document.getElementById('photo-viewer').classList.add('show');
                        }
                        if (el && el.id === 'photo-viewer-close') {
                            document.getElementById('photo-viewer').classList.remove('show');
                        }
                    });
                    document.getElementById('btn-case-search').addEventListener('click', loadCases);
                    document.getElementById('btn-timeline-refresh').addEventListener('click', loadTimeline);

                    // ---------------- 消息：开票 / 发货 ----------------
                    document.getElementById('btn-invoice-refresh').addEventListener('click', loadOrders);
                    document.getElementById('btn-ship-refresh').addEventListener('click', loadOrders);
                    document.getElementById('btn-ship-all').addEventListener('click', function () {
                        var list = (ordersData.groups || {}).ship || [];
                        list.forEach(function (o) { shipPicked[o.id] = o; });
                        renderShipList();
                    });
                    document.getElementById('btn-ship-none').addEventListener('click', function () {
                        shipPicked = {};
                        renderShipList();
                    });
                    document.getElementById('btn-ship-open').addEventListener('click', openShipSheet);
                    document.getElementById('ship-close').addEventListener('click', function () {
                        document.getElementById('ship-sheet').style.display = 'none';
                    });
                    document.getElementById('btn-ship-confirm').addEventListener('click', submitShip);
                    document.getElementById('btn-ship-scan').addEventListener('click', scanTracking);
                    document.getElementById('btn-ship-camera').addEventListener('click', function () {
                        document.getElementById('ship-camera-input').click();
                    });
                    document.getElementById('btn-ship-album').addEventListener('click', function () {
                        document.getElementById('ship-photo-input').click();
                    });
                    document.getElementById('btn-ship-paste').addEventListener('click', function () {
                        var input = document.getElementById('ship-tracking');
                        if (navigator.clipboard && navigator.clipboard.readText) {
                            navigator.clipboard.readText().then(function (txt) {
                                txt = (txt || '').trim();
                                if (txt) { input.value = txt; toast('已粘贴快递单号'); }
                                else { toast('剪贴板是空的'); }
                            }).catch(function () {
                                input.focus();
                                toast('请长按输入框手动粘贴');
                            });
                        } else {
                            input.focus();
                            toast('请长按输入框手动粘贴');
                        }
                    });
                    document.getElementById('ship-photo-input').addEventListener('change', function (ev) {
                        addShipPhotos(ev.target.files);
                        ev.target.value = '';
                    });
                    document.getElementById('ship-camera-input').addEventListener('change', function (ev) {
                        addShipPhotos(ev.target.files);
                        ev.target.value = '';
                    });
                    // 待发货工单勾选（列表是动态渲染的，用事件委托）
                    document.addEventListener('change', function (ev) {
                        var el = ev.target;
                        if (!el || !el.getAttribute) { return; }
                        var id = el.getAttribute('data-ship-pick');
                        if (!id) { return; }
                        var list = (ordersData.groups || {}).ship || [];
                        var found = null;
                        list.forEach(function (o) { if (String(o.id) === String(id)) { found = o; } });
                        if (el.checked && found) { shipPicked[id] = found; }
                        else { delete shipPicked[id]; }
                        updateShipButton();
                    });
                    // 删除已拍好的包装照片
                    document.addEventListener('click', function (ev) {
                        var el = ev.target;
                        if (!el || !el.getAttribute) { return; }
                        var idx = el.getAttribute('data-shipphoto-del');
                        if (idx !== null && idx !== undefined && idx !== '') {
                            shipPhotos.splice(Number(idx), 1);
                            renderShipThumbs();
                        }
                    });
                    document.getElementById('btn-logout').addEventListener('click', function () {
                        askConfirm('确认退出登录？', function () {
                            window.location.href = '/web/session/logout?redirect=/web/login';
                        });
                    });

                    function switchMsgTab(name) {
                        document.querySelectorAll('[data-msg-tab]').forEach(function (b) {
                            if (b.getAttribute('data-msg-tab') === name) { b.classList.add('active'); }
                            else { b.classList.remove('active'); }
                        });
                        document.getElementById('msg-timeline').style.display =
                            (name === 'timeline') ? 'block' : 'none';
                        document.getElementById('msg-discuss').style.display =
                            (name === 'discuss') ? 'block' : 'none';
                        document.getElementById('msg-invoice').style.display =
                            (name === 'invoice') ? 'block' : 'none';
                        document.getElementById('msg-ship').style.display =
                            (name === 'ship') ? 'block' : 'none';
                        if (name === 'discuss') {
                            var frame = document.getElementById('discuss-frame');
                            if (frame && !frame.getAttribute('src')) {
                                frame.setAttribute('src', '/odoo/discuss');
                            }
                        }
                        if (name === 'invoice' || name === 'ship') {
                            // 这两个分栏看的是全厂待办，每次进来都拉一次最新数据
                            loadOrders();
                        }
                    }
                    document.querySelectorAll('[data-msg-tab]').forEach(function (b) {
                        b.addEventListener('click', function () {
                            switchMsgTab(b.getAttribute('data-msg-tab'));
                        });
                    });

                    function loadTimeline() {
                        post('/timeline', {}).then(function (res) {
                            var box = document.getElementById('timeline-list');
                            if (!res.ok) { box.innerHTML = '<div class="empty">读取失败</div>'; return; }
                            if (!res.events || !res.events.length) {
                                box.innerHTML = '<div class="empty">暂无动态</div>'; return;
                            }
                            box.innerHTML = res.events.map(function (e) {
                                var sys = e.kind === 'system';
                                return '<div class="tl ' + (sys ? 'tl-sys' : 'tl-chat') + '">' +
                                    '<div class="tl-head"><span class="tag ' + (sys ? 'info' : 'ok') + '">' +
                                    esc(e.title) + '</span> <b>' + esc(e.order) + '</b> · ' +
                                    stateTag(e.state) + ' · ' + esc(e.date) +
                                    (e.author ? ' · ' + esc(e.author) : '') + '</div>' +
                                    (e.body ? '<div class="tl-body">' + esc(e.body) + '</div>' : '') +
                                    '</div>';
                            }).join('');
                        }).catch(function () {
                            document.getElementById('timeline-list').innerHTML =
                                '<div class="empty">当前离线，稍后再试</div>';
                        });
                    }
                    function loadCases() {
                        var q = document.getElementById('case-q').value.trim();
                        post('/cases', {q: q}).then(function (res) {
                            var box = document.getElementById('case-list');
                            if (!res.ok) { box.innerHTML = '<div class="empty">读取失败</div>'; return; }
                            box.innerHTML = (res.cases && res.cases.length)
                                ? res.cases.map(function (c) {
                                    return '<div class="order"><div class="info"><b>' + esc(c.machine_no) +
                                        '</b> · ' + esc(c.date) + ' · ' + esc(c.technician) +
                                        '<br/>故障：' + (esc(c.fault) || '-') +
                                        '<br/>处理：' + (esc(c.solution) || '-') +
                                        (c.parts ? '<br/>配件：' + esc(c.parts) : '') + '</div></div>';
                                }).join('')
                                : '<div class="empty">没有匹配的经验</div>';
                        }).catch(function () {
                            document.getElementById('case-list').innerHTML =
                                '<div class="empty">当前离线，稍后再试</div>';
                        });
                    }

                    // ---------------- 自绘确认框（避免 WebView 原生 confirm 显示网址） ----------------
                    var confirmCallback = null;
                    var confirmCancelCallback = null;

                    function askConfirm(message, onOk, onCancel) {
                        confirmCallback = onOk || null;
                        confirmCancelCallback = onCancel || null;
                        document.getElementById('confirm-text').textContent = message;
                        document.getElementById('confirm-mask').classList.add('show');
                    }
                    document.getElementById('confirm-ok').addEventListener('click', function () {
                        var cb = confirmCallback;
                        confirmCallback = null;
                        confirmCancelCallback = null;
                        document.getElementById('confirm-mask').classList.remove('show');
                        if (cb) { cb(); }
                    });
                    document.getElementById('confirm-cancel').addEventListener('click', function () {
                        var cb = confirmCancelCallback;
                        confirmCallback = null;
                        confirmCancelCallback = null;
                        document.getElementById('confirm-mask').classList.remove('show');
                        if (cb) { cb(); }
                    });

                    // ---------------- 加载遮罩 ----------------
                    function showLoading(text) {
                        document.getElementById('loading-text').textContent = text || '正在处理…';
                        document.getElementById('loading-mask').classList.add('show');
                    }
                    function hideLoading() {
                        document.getElementById('loading-mask').classList.remove('show');
                    }

                    // ---------------- 圆环进度（上传 / 转发下载共用） ----------------
                    // 圆周长 = 2πr = 2 × 3.14159 × 38 ≈ 238.76，用 stroke-dashoffset 控制显示比例
                    var PROGRESS_CIRCUM = 238.76;

                    function showProgress(title) {
                        setProgress(0, title || '');
                        document.getElementById('progress-mask').classList.add('show');
                    }
                    function setProgress(percent, hint) {
                        var pct = Math.max(0, Math.min(100, Math.round(Number(percent) || 0)));
                        var ring = document.getElementById('progress-ring');
                        if (ring) {
                            ring.style.strokeDashoffset = String(PROGRESS_CIRCUM * (1 - pct / 100));
                        }
                        var text = document.getElementById('progress-text');
                        if (text) { text.textContent = pct + '%'; }
                        var hintEl = document.getElementById('progress-hint');
                        if (hintEl && hint !== undefined && hint !== null) { hintEl.textContent = hint; }
                    }
                    function hideProgress() {
                        document.getElementById('progress-mask').classList.remove('show');
                    }
                    function fmtBytes(n) {
                        n = Number(n) || 0;
                        if (n >= 1024 * 1024) { return (n / 1024 / 1024).toFixed(1) + ' MB'; }
                        if (n >= 1024) { return Math.round(n / 1024) + ' KB'; }
                        return n + ' B';
                    }
                    // App 原生下载（转发前）的进度回调；-1 表示拿不到总大小
                    window.onNativeShareProgress = function (pct) {
                        if (pct === undefined || pct === null) { return; }
                        if (pct < 0) {
                            var hint = document.getElementById('progress-hint');
                            if (hint) { hint.textContent = '正在下载视频到手机…'; }
                            return;
                        }
                        setProgress(pct, '正在下载视频到手机…');
                    };

                    // ---------------- 工单详情 ----------------
                    var detailOrder = null;
                    var openingOrder = false;

                    function openOrder(orderId) {
                        if (openingOrder) { return; }        // 防重复点击
                        openingOrder = true;
                        showLoading('正在打开工单…');
                        var done = false;
                        var finish = function () {
                            if (done) { return; }
                            done = true;
                            hideLoading();
                            openingOrder = false;
                        };
                        // 看门狗：12 秒还没回来就解除，避免"永远转圈"
                        var watchdog = setTimeout(function () { finish(); toast('打开超时，请检查网络后重试'); }, 12000);
                        post('/order_detail', {order_id: orderId}).then(function (res) {
                            clearTimeout(watchdog);
                            finish();
                            if (!res.ok) { toast(res.error || '读取失败'); return; }
                            detailOrder = res.order;
                            renderDetail(res.order);
                            document.getElementById('order-detail').style.display = 'block';
                            window.scrollTo(0, 0);
                        }).catch(function () {
                            clearTimeout(watchdog);
                            finish();
                            toast('网络不稳，打开失败，请重试');
                        });
                    }

                    // ---------------- 详情：机台 / 板件补填 ----------------
                    function loadFixBoard(o) {
                        var mSel = document.getElementById('d-machine');
                        if (!mSel) { return; }
                        if (!o.partner_id) {
                            mSel.innerHTML = '<option value="">（这张工单没有客户，无法列机台）</option>';
                            return;
                        }
                        post('/machines', {partner_id: o.partner_id}).then(function (res) {
                            if (!res.ok) { toast(res.error || '读不到机台列表'); return; }
                            if (!res.machines.length) {
                                mSel.innerHTML = '<option value="">（该客户还没有机台）</option>';
                                return;
                            }
                            mSel.innerHTML = '<option value="">（选择机台）</option>' +
                                res.machines.map(function (m) {
                                    return '<option value="' + m.id + '">' + esc(m.no) +
                                        (m.model ? ' · ' + esc(m.model) : '') + '</option>';
                                }).join('');
                            if (o.machine_id) { mSel.value = String(o.machine_id); }
                            loadFixProducts(o);
                        }).catch(function () { toast('网络不稳，读不到机台列表'); });
                    }

                    function loadFixProducts(o) {
                        var pSel = document.getElementById('d-product');
                        var mSel = document.getElementById('d-machine');
                        if (!pSel || !mSel) { return; }
                        pSel.innerHTML = '<option value="">（加载中…）</option>';
                        post('/boards', {machine_id: mSel.value || ''}).then(function (res) {
                            if (!res.ok || !res.boards.length) {
                                pSel.innerHTML = '<option value="">（还没有电路板产品）</option>';
                                return;
                            }
                            pSel.innerHTML = '<option value="">（选择板件型号）</option>' +
                                res.boards.map(function (b) {
                                    return '<option value="' + b.id + '">' +
                                        (b.is_model ? '★ ' : '') + esc(b.name) + '</option>';
                                }).join('');
                            if (o && o.product_id) { pSel.value = String(o.product_id); }
                        }).catch(function () { pSel.innerHTML = '<option value="">（读取失败）</option>'; });
                    }

                    // ---------------- 视频分享 ----------------
                    // navigator.share() 必须在**点击事件的第一层同步调用**。
                    // 以前是先 fetch 视频、再 share —— 异步回来时用户手势已经过期，
                    // 浏览器直接拒绝（NotAllowedError），表现就是“点分享毫无反应”。
                    // 现在的做法：
                    //   1) 详情页渲染时后台把视频预取成 File 缓存（≤30MB）；
                    //   2) 点击时文件已就绪 -> 同步 navigator.share({files})；
                    //   3) 还没就绪 -> 立刻同步分享链接（同样保住手势）；
                    //   4) 不支持分享的浏览器（安卓 WebView、部分国产浏览器）弹出可见的降级面板。
                    var shareFiles = {};        // video_id -> File
                    var sharePending = {};      // video_id -> pending promise

                    function prepareVideoShare(o) {
                        if (!navigator.share) { return; }
                        // 开了省流量模式就别偷偷预下载视频，改用链接分享
                        if (navigator.connection && navigator.connection.saveData) { return; }
                        (o.videos || []).forEach(function (v) {
                            if (!v || !v.id || shareFiles[v.id] || sharePending[v.id]) { return; }
                            if (v.size && v.size > 80 * 1024 * 1024) { return; }
                            sharePending[v.id] = fetch(BASE + '/video/' + v.id,
                                                       {credentials: 'same-origin'})
                                .then(function (r) {
                                    if (!r.ok) { throw new Error('HTTP ' + r.status); }
                                    return r.blob();
                                })
                                .then(function (blob) {
                                    try {
                                        shareFiles[v.id] = new File(
                                            [blob], v.name || ('video-' + v.id + '.mp4'),
                                            {type: blob.type || 'video/mp4'});
                                    } catch (e) { /* 老内核没有 File 构造器，只能分享链接 */ }
                                })
                                .catch(function () { })
                                .then(function () { delete sharePending[v.id]; });
                        });
                    }

                    function videoById(id) {
                        var list = (detailOrder && detailOrder.videos) || [];
                        for (var i = 0; i < list.length; i++) {
                            if (String(list[i].id) === String(id)) { return list[i]; }
                        }
                        return null;
                    }

                    function absoluteUrl(path) {
                        return /^https?:\/\//i.test(path) ? path : (window.location.origin + path);
                    }

                    function legacyCopy(text) {
                        return new Promise(function (resolve, reject) {
                            try {
                                var ta = document.createElement('textarea');
                                ta.value = text;
                                ta.setAttribute('readonly', 'readonly');
                                ta.style.cssText = 'position:fixed;top:-1000px;left:0;opacity:0';
                                document.body.appendChild(ta);
                                ta.select();
                                ta.setSelectionRange(0, text.length);
                                var ok = document.execCommand && document.execCommand('copy');
                                document.body.removeChild(ta);
                                ok ? resolve() : reject(new Error('copy unsupported'));
                            } catch (e) { reject(e); }
                        });
                    }

                    function copyText(text) {
                        // 剪贴板 API 要安全上下文 + 用户手势，WebView / 老浏览器里常常没有；
                        // 退回到 textarea + execCommand，总比“什么都不发生”强。
                        if (navigator.clipboard && navigator.clipboard.writeText) {
                            return navigator.clipboard.writeText(text).catch(function () {
                                return legacyCopy(text);
                            });
                        }
                        return legacyCopy(text);
                    }

                    function showShareFallback(video, url) {
                        if (document.getElementById('share-box')) { return; }
                        var box = document.createElement('div');
                        box.id = 'share-box';
                        box.className = 'card';
                        box.style.cssText = 'position:fixed;left:12px;right:12px;bottom:76px;' +
                            'z-index:120;box-shadow:0 10px 30px rgba(40,20,70,.35)';
                        box.innerHTML =
                            '<h2>转发这段视频</h2>' +
                            '<div class="hint">这个浏览器不支持系统转发面板（微信/QQ 内置浏览器都不支持）。' +
                            '请先<b>下载视频</b>，再打开微信/QQ，在聊天里选「相册 → 刚下载的视频」发出去。</div>' +
                            '<div class="row" style="margin-top:10px">' +
                            '<a class="btn small ok" id="share-download" style="flex:1;margin:0" ' +
                            'href="' + escAttr(url) + '" download="' + escAttr(video.name || 'video.mp4') +
                            '">下载视频</a>' +
                            '<button class="btn small ghost" id="share-copy" style="flex:1;margin:0">复制链接</button>' +
                            '</div>' +
                            '<input type="text" id="share-url" readonly value="' + escAttr(url) +
                            '" style="margin-top:8px"/>' +
                            '<div class="row" style="margin-top:8px">' +
                            '<button class="btn small ghost" id="share-open" style="flex:1;margin:0">播放视频</button>' +
                            '<button class="btn small ghost" id="share-close" style="flex:1;margin:0">关闭</button>' +
                            '</div>';
                        document.body.appendChild(box);
                        document.getElementById('share-close').onclick = function () {
                            if (box.parentNode) { box.parentNode.removeChild(box); }
                        };
                        document.getElementById('share-open').onclick = function () {
                            window.open(url, '_blank');
                        };
                        document.getElementById('share-download').onclick = function () {
                            // App 里 <a download> 走原生下载器；浏览器里就是普通下载
                            toast('开始下载视频，下载完去微信/QQ 里选择它发送');
                        };
                        document.getElementById('share-copy').onclick = function () {
                            copyText(url).then(function () {
                                toast('链接已复制，粘贴发给对方即可');
                            }).catch(function () {
                                var input = document.getElementById('share-url');
                                if (input) { input.focus(); input.select(); }
                                toast('请长按上面的链接手动复制');
                            });
                        };
                    }

                    function shareVideo(videoId) {
                        var video = videoById(videoId);
                        if (!video) { toast('视频不存在，请刷新后重试'); return; }
                        var url = absoluteUrl(video.url);
                        var name = video.name || 'video.mp4';
                        var file = shareFiles[videoId];

                        // 1) App 内：交给原生下载 + 系统「分享/转发」面板（微信、QQ 都在列表里），
                        //    转发的是视频文件本身，不是链接。
                        if (NATIVE && NATIVE.shareVideo) {
                            showProgress('正在下载视频…');
                            setProgress(0, '正在准备视频…');
                            // 兜底：万一原生回调没回来，3 分钟后自己收掉进度环
                            clearTimeout(window.__shareWatch);
                            window.__shareWatch = setTimeout(function () {
                                hideProgress();
                                toast('准备超时，请检查网络后重试', 5000);
                            }, 180000);
                            try {
                                NATIVE.shareVideo(url, name);
                            } catch (e) {
                                hideProgress();
                                toast('原生转发调用失败，改用浏览器分享');
                            }
                            return;
                        }

                        // 2) 浏览器：Web Share Level 2 可以直接把文件交给系统分享面板
                        if (navigator.share) {
                            var hasFile = !!(file && (!navigator.canShare || navigator.canShare({files: [file]})));
                            var data = hasFile
                                ? {files: [file], title: name}
                                : {title: name, text: '维修视频：' + name, url: url};
                            try {
                                navigator.share(data).then(function () {
                                    toast(hasFile ? '已打开系统转发面板' : '已打开系统分享（链接）');
                                }).catch(function (err) {
                                    if (err && err.name === 'AbortError') { return; }   // 用户自己取消
                                    // 文件分享失败（大小/类型不支持）时退回链接分享再试一次
                                    if (hasFile) {
                                        navigator.share({title: name, text: '维修视频：' + name, url: url})
                                            .catch(function () { showShareFallback(video, url); });
                                        return;
                                    }
                                    toast('分享失败：' + ((err && err.name) || '未知错误'));
                                    showShareFallback(video, url);
                                });
                                return;
                            } catch (e) {
                                toast('系统分享调用失败，改为下载后转发');
                            }
                        }
                        showShareFallback(video, url);
                    }

                    // App 原生转发结果回调（Java 里下载完/失败都会调一次）
                    window.onNativeShare = function (ok, message) {
                        clearTimeout(window.__shareWatch);
                        hideProgress();
                        hideLoading();
                        if (ok) { toast(message || '已打开转发面板，选微信 / QQ 即可', 5000); }
                        else { toast('转发失败：' + (message || '未知原因'), 6000); }
                    };

                    function renderDetail(o) {
                        document.getElementById('d-title').textContent = o.name + ' · ' + o.state;
                        var m = o.measure || {};
                        var measureRow = function (key, label) {
                            var done = !!m[key];
                            return '<div class="measure-item"><span>' + label + '</span>' +
                                (done
                                    ? '<span class="tag ok">已完成</span>'
                                    : '<button class="btn small" data-measure="' + key +
                                      '" style="margin:0">完成</button>') + '</div>';
                        };
                        var videos = (o.videos || []).map(function (v) {
                            // 属性里只放 video id：以前把 id|url|文件名拼成字符串，
                            // 文件名里一旦有 | 或引号，属性就被截断，按钮点了没反应。
                            return '<div style="margin-bottom:10px">' +
                                '<video src="' + escAttr(v.url) + '" controls preload="metadata" playsinline="1" ' +
                                'style="width:100%;max-height:200px;border-radius:10px;background:#000"></video>' +
                                '<div class="video-item"><span>' + esc(v.name) + '（' + v.duration + ' 秒）</span>' +
                                '<span>' +
                                '<a class="btn small ghost" href="' + escAttr(v.url) + '" download="' +
                                escAttr(v.name) + '" style="margin-right:6px">下载</a>' +
                                '<button class="btn small ghost" data-sharevideo="' + v.id +
                                '" style="margin:0 6px 0 0">转发</button>' +
                                '<button class="btn small ghost" data-delvideo="' + v.id +
                                '" style="margin:0">删除</button></span></div></div>';
                        }).join('') || '<div class="empty">还没有视频（完工前必须上传至少 1 段）</div>';

                        var html = '';
                        html += kv('客户', o.partner);
                        if (o.machine_missing || o.product_missing) {
                            // 扫码建单时没带出机台/板件，详情就只剩 '-'。
                            // 这里给出补填入口，写回工单（顺带写回二维码），下次扫码就有档案。
                            html += '<div class="warnbox" style="margin:8px 0">' +
                                '这张工单还缺 <b>' +
                                (o.machine_missing ? '机台' : '') +
                                (o.machine_missing && o.product_missing ? ' / ' : '') +
                                (o.product_missing ? '板件型号' : '') +
                                '</b>，补填后详情和报表里就会正常显示。' +
                                (o.qr ? '<div style="margin-top:4px">二维码：' + esc(o.qr) + '</div>' : '') +
                                '<select id="d-machine" style="margin-top:8px">' +
                                '<option value="">（选择机台）</option></select>' +
                                '<select id="d-product" style="margin-top:6px">' +
                                '<option value="">（先选机台，再选板件型号）</option></select>' +
                                '<button class="btn small ghost" data-fixboard="1" ' +
                                'style="margin-top:8px">补填机台 / 板件</button>' +
                                '</div>';
                        }
                        html += kv('机台', o.machine) + kv('板件', o.product);
                        html += kv('二维码', o.qr) + kv('紧急度', o.urgency) + kv('期限', o.deadline);
                        html += kv('师傅', o.technician);
                        html += '<div class="hint" style="margin-top:10px">错误代码</div>' +
                                '<input type="text" id="d-errcode" placeholder="如 E-021" value="' +
                                escAttr(o.error_code) + '"/>';
                        html += '<div class="hint" style="margin-top:10px">故障描述</div>' +
                                '<textarea id="d-fault">' + esc(o.fault) + '</textarea>';
                        html += '<div class="hint" style="margin-top:10px">故障分析判断</div>' +
                                '<textarea id="d-analysis">' + esc(o.analysis) + '</textarea>';
                        html += '<div class="hint" style="margin-top:10px">维修过程</div>' +
                                '<textarea id="d-process">' + esc(o.process) + '</textarea>';
                        html += '<button class="btn ghost" data-savework="1" style="margin-top:8px">保存以上内容</button>';

                        var dPhotos = (o.photos || []).map(function (p) {
                            var small = window.location.origin + p.url;
                            return '<div style="margin:0 8px 8px 0;text-align:center">' +
                                '<img src="' + small + '" data-photo-view="' + small +
                                '" style="width:74px;height:74px;object-fit:cover;cursor:zoom-in;' +
                                'border-radius:8px;border:1px solid #e6dff2"/>' +
                                '<div style="font-size:11px"><a href="' + small + '" download="' + p.label +
                                '.jpg">下载</a></div></div>';
                        }).join('') || '<div class="empty">还没有照片</div>';
                        html += '<div class="card" style="margin-top:12px"><h2>电路板照片</h2>' +
                                '<div class="thumbs" style="display:flex;flex-wrap:wrap">' + dPhotos + '</div>' +
                                '</div>';

                        html += '<div class="card" style="margin-top:12px"><h2>电气参数测量</h2>' +
                                measureRow('resistance', '电阻') + measureRow('voltage', '电压') +
                                measureRow('inductance', '电感') + measureRow('capacitance', '电容') +
                                (m.note ? '<div class="hint" style="margin-top:8px">' + esc(m.note) + '</div>' : '') +
                                '</div>';

                        html += '<div class="card"><h2>维修视频（最多 3 段，每段 ≤5 分钟）</h2>' +
                                videos +
                                '<div class="row" style="margin-top:8px">' +
                                '<button class="btn small" id="btn-video-record" style="margin:0">录制视频</button>' +
                                '<button class="btn small ghost" id="btn-video-upload" style="margin:0">' +
                                '从相册 / 文件上传</button>' +
                                '</div>' +
                                '<div class="hint" style="margin-top:6px">' +
                                '「录制」直接用相机拍；「从相册 / 文件上传」选手机里已有的视频（可一次选多段）。' +
                                '</div>' +
                                '</div>';

                        var req = o.requirements || {};
                        var okFlag = function (done) {
                            return done ? '<span class="tag ok">已满足</span>'
                                        : '<span class="tag bad">未满足</span>';
                        };
                        html += '<div class="card" style="margin-top:12px"><h2>完工条件</h2>' +
                            '<div class="measure-item"><span>正反面照片（正 ' + (req.front || 0) +
                            ' / 反 ' + (req.back || 0) + '）</span>' + okFlag(req.photos_ok) + '</div>' +
                            '<div class="measure-item"><span>维修视频（' + (req.videos || 0) +
                            ' 段，至少 1 段）</span>' + okFlag(req.videos_ok) + '</div>' +
                            '<div class="measure-item"><span>电气测量（' + (req.measures_done || 0) +
                            ' / ' + (req.measures_total || 4) + '）</span>' +
                            (req.measures_done ? '<span class="tag info">已完成 ' + req.measures_done + ' 项</span>'
                                               : '<span class="tag warn">未开始</span>') + '</div>' +
                            '</div>';

                        // 发货 + 保修：已发货的工单能查到快递单号和包装照片
                        var ship = o.shipment;
                        html += '<div class="card" style="margin-top:12px"><h2>发货</h2>';
                        if (ship) {
                            html += kv('发货单', ship.name);
                            html += kv('快递单号', ship.tracking_no);
                            html += kv('快递公司', ship.carrier);
                            html += kv('发货时间', ship.ship_date);
                            var shipPhotosHtml = (ship.photos || []).map(function (p) {
                                var url = window.location.origin + p.url;
                                return '<div style="margin:0 8px 8px 0;text-align:center">' +
                                    '<img src="' + url + '" data-photo-view="' + url +
                                    '" style="width:74px;height:74px;object-fit:cover;cursor:zoom-in;' +
                                    'border-radius:8px;border:1px solid #e6dff2"/>' +
                                    '<div style="font-size:11px"><a href="' + url +
                                    '" download="包装照片.jpg">下载</a></div></div>';
                            }).join('') || '<div class="empty">没有包装照片</div>';
                            html += '<div class="thumbs" style="display:flex;flex-wrap:wrap">' +
                                shipPhotosHtml + '</div>';
                        } else if (o.done) {
                            html += '<div class="warnbox" style="margin:0">这张工单<b>还没有发货</b>。' +
                                '请管理员扫快递单号、拍包装照片后点「确定发货」。</div>' +
                                '<button class="btn ok" data-shipfromdetail="' + o.id +
                                '" style="margin-top:10px">去发货</button>';
                        } else {
                            html += '<div class="hint">工单完工后才能发货。</div>';
                        }
                        if (o.warranty_pending) {
                            html += '<div class="hint" style="margin-top:8px;color:#8a5b00">' +
                                '活期客户 + 首次维修：保修从<b>发货快递时间</b>起算（' +
                                (o.warranty_months || 12) + ' 个月）。</div>';
                        } else if (o.warranty_months) {
                            html += '<div class="hint" style="margin-top:8px">本次保修：' +
                                o.warranty_months + ' 个月。</div>';
                        }
                        html += '</div>';

                        var canComplete = o.can_complete;
                        html += '<div class="hint" style="margin:6px 0">当前状态：' + esc(o.state) + '</div>';
                        html += '<div class="row">' +
                            (o.done
                                ? '<button class="btn ok" style="flex:1;margin:0" disabled="disabled">已完工</button>'
                                : canComplete
                                    ? '<button class="btn ok" data-complete="' + o.id +
                                      '" style="flex:1;margin:0">提交完工</button>'
                                    : '<button class="btn" data-claim="' + o.id +
                                      '" style="flex:1;margin:0">先抢单再完工</button>') +
                            '</div>';
                        if (!o.done && !req.videos_ok) {
                            html += '<div class="hint" style="color:#c0392b;margin-top:6px">' +
                                '还差维修视频：上传至少 1 段后才能提交完工。</div>';
                        }
                        var sheet = document.getElementById('order-detail');
                        var keepScroll = (sheet.style.display === 'block') ? sheet.scrollTop : 0;
                        document.getElementById('d-body').innerHTML = html;
                        // 换 innerHTML 会丢滚动位置：新打开的详情回到顶部，
                        // 就地刷新（勾测量、删视频、补填）则停在原来的位置。
                        sheet.scrollTop = keepScroll;
                        var hint = document.getElementById('d-hint');
                        if (hint) { hint.textContent = ''; }
                        if (o.machine_missing || o.product_missing) { loadFixBoard(o); }
                        prepareVideoShare(o);
                    }

                    document.getElementById('d-close').addEventListener('click', function () {
                        document.getElementById('order-detail').style.display = 'none';
                        var box = document.getElementById('share-box');
                        if (box && box.parentNode) { box.parentNode.removeChild(box); }
                        detailOrder = null;
                    });

                    // 选机台 -> 刷新板件型号下拉（补填用）
                    document.getElementById('order-detail').addEventListener('change', function (ev) {
                        var el = ev.target;
                        if (el && el.id === 'd-machine') { loadFixProducts(detailOrder); }
                    });

                    document.getElementById('order-detail').addEventListener('click', function (ev) {
                        var el = ev.target, v;
                        if (!el || !el.getAttribute) { return; }
                        // 详情页自己处理这些动作；不阻断的话，同一个点击会被
                        // 页面底下的全局委托再处理一遍（完工弹两次确认框就是这个问题）。
                        if (el.getAttribute('data-measure') || el.getAttribute('data-savework') ||
                            el.getAttribute('data-fixboard') || el.getAttribute('data-sharevideo') ||
                            el.getAttribute('data-delvideo') || el.getAttribute('data-complete') ||
                            el.getAttribute('data-shipfromdetail') ||
                            el.id === 'btn-video') {
                            ev.stopPropagation();
                        }
                        if ((v = el.getAttribute('data-shipfromdetail'))) {
                            if (!detailOrder) { return; }
                            shipPicked = {};
                            shipPicked[detailOrder.id] = {
                                id: detailOrder.id, name: detailOrder.name,
                                state: detailOrder.state, state_key: 'done',
                                machine: detailOrder.machine, partner: detailOrder.partner
                            };
                            openShipSheet();
                            return;
                        }
                        if ((v = el.getAttribute('data-measure'))) {
                            var label = ({resistance: '电阻', voltage: '电压',
                                          inductance: '电感', capacitance: '电容'})[v] || v;
                            askConfirm('确认「' + label + '」已测量完成？', function () {
                                post('/measure', {order_id: detailOrder.id, kind: v}).then(function (res) {
                                    if (!res.ok) { toast(res.error || '保存失败'); return; }
                                    toast(label + '：已完成');
                                    // 本地更新，不再重新拉整个详情（省一次往返）
                                    detailOrder.measure[v] = true;
                                    renderDetail(detailOrder);
                                });
                            });
                            return;
                        }
                        if (el.getAttribute('data-savework')) {
                            var vals = {
                                order_id: detailOrder.id,
                                fault: document.getElementById('d-fault').value,
                                analysis: document.getElementById('d-analysis').value,
                                process: document.getElementById('d-process').value
                            };
                            var errEl = document.getElementById('d-errcode');
                            if (errEl) { vals.error_code = errEl.value; }
                            post('/save_work', vals).then(function (res) {
                                toast(res.ok ? '已保存' : (res.error || '保存失败'));
                                if (res.ok) { openOrder(detailOrder.id); }
                            }).catch(function () { toast('网络不稳，没保存成功，请重试'); });
                            return;
                        }
                        if (el.getAttribute('data-fixboard')) {
                            var mSel = document.getElementById('d-machine');
                            var pSel = document.getElementById('d-product');
                            if (!mSel || !pSel) { return; }
                            if (!mSel.value || !pSel.value) { toast('机台和板件型号都要选'); return; }
                            post('/save_work', {order_id: detailOrder.id,
                                                 machine_id: mSel.value,
                                                 product_id: pSel.value}).then(function (res) {
                                toast(res.ok ? '已补填机台 / 板件' : (res.error || '补填失败'));
                                if (res.ok) { openOrder(detailOrder.id); }
                            }).catch(function () { toast('网络不稳，补填没提交成功'); });
                            return;
                        }
                        if ((v = el.getAttribute('data-sharevideo'))) {
                            shareVideo(v);
                            return;
                        }
                        if ((v = el.getAttribute('data-delvideo'))) {
                            askConfirm('确认删除这段视频？', function () {
                                post('/delete_video', {video_id: v}).then(function (res) {
                                    toast(res.ok ? '已删除' : (res.error || '删除失败'));
                                    if (res.ok) {
                                        detailOrder.videos = detailOrder.videos.filter(function (x) {
                                            return String(x.id) !== String(v);
                                        });
                                        renderDetail(detailOrder);
                                    }
                                });
                            });
                            return;
                        }
                        if ((v = el.getAttribute('data-complete'))) {
                            var reqV = (detailOrder && detailOrder.requirements) || {};
                            if (!reqV.videos_ok) {
                                toast('还没有上传维修视频，无法提交完工');
                                return;
                            }
                            askConfirm('确认所有维修已完成并提交完工？', function () {
                                showLoading('正在提交完工…');
                                post('/complete', {order_id: v}).then(function (res) {
                                    hideLoading();
                                    if (!res.ok) { toast(res.error || '完工失败'); return; }
                                    toast('已完工：' + res.order_name);
                                    document.getElementById('order-detail').style.display = 'none';
                                    loadOrders();
                                }).catch(function () {
                                    hideLoading();
                                    toast('网络不稳，完工没提交成功');
                                });
                            });
                            return;
                        }
                    });

                    // 视频按钮是详情渲染时才生成的，必须用事件委托。
                    // 之前这里直接 getElementById('btn-video') 会返回 null，
                    // 抛出异常后把后续所有绑定都中断了（点视频没反应的真凶）。
                    document.getElementById('order-detail').addEventListener('click', function (ev) {
                        var el = ev.target;
                        if (!el) { return; }
                        var id = el.id || (el.parentNode && el.parentNode.id);
                        if (id === 'btn-video-record') {
                            // 录制：带 capture 的 input，手机直接开相机
                            document.getElementById('video-record-input').click();
                        } else if (id === 'btn-video-upload' || id === 'btn-video') {
                            // 从相册 / 文件上传：不带 capture，可多选
                            document.getElementById('video-input').click();
                        }
                    });

                    // 单个视频：先读时长（≤5 分钟），再用 XHR 上传（能拿到上传进度）
                    function uploadVideoFile(file, label) {
                        return new Promise(function (resolve) {
                            if (!file || !detailOrder) { resolve(false); return; }
                            var url = URL.createObjectURL(file);
                            var probe = document.createElement('video');
                            probe.preload = 'metadata';
                            probe.onloadedmetadata = function () {
                                var dur = Math.round(probe.duration || 0);
                                URL.revokeObjectURL(url);
                                if (!dur) {
                                    hideProgress();
                                    toast('读不到视频时长，请换一个格式');
                                    resolve(false);
                                    return;
                                }
                                if (dur > 300) {
                                    hideProgress();
                                    toast('视频 ' + dur + ' 秒，超过 5 分钟，请换一段');
                                    resolve(false);
                                    return;
                                }
                                var fd = new FormData();
                                fd.append('csrf_token', CSRF);
                                fd.append('order_id', detailOrder.id);
                                fd.append('duration', dur);
                                fd.append('video', file, file.name || 'repair.mp4');

                                var xhr = new XMLHttpRequest();
                                xhr.open('POST', BASE + '/upload_video');
                                xhr.withCredentials = true;
                                xhr.timeout = 15 * 60 * 1000;
                                xhr.upload.onprogress = function (ev) {
                                    if (!ev.lengthComputable) {
                                        setProgress(0, (label || '') + ' 上传中…');
                                        return;
                                    }
                                    setProgress(ev.loaded / ev.total * 100,
                                        (label ? label + ' · ' : '') +
                                        fmtBytes(ev.loaded) + ' / ' + fmtBytes(ev.total));
                                };
                                xhr.onload = function () {
                                    var res = null;
                                    try { res = JSON.parse(xhr.responseText || '{}'); } catch (e) { res = null; }
                                    if (!res || !res.ok) {
                                        hideProgress();
                                        toast((res && res.error) ||
                                              ('上传失败（HTTP ' + xhr.status + '）'), 6000);
                                        resolve(false);
                                        return;
                                    }
                                    setProgress(100, (label ? label + ' · ' : '') + '已上传');
                                    resolve(true);
                                };
                                xhr.onerror = function () {
                                    hideProgress();
                                    toast('网络不稳，视频上传失败，请重试', 6000);
                                    resolve(false);
                                };
                                xhr.ontimeout = function () {
                                    hideProgress();
                                    toast('上传超时，请检查网络后重试', 6000);
                                    resolve(false);
                                };
                                xhr.send(fd);
                            };
                            probe.onerror = function () {
                                hideProgress();
                                toast('这个视频格式读不出时长');
                                resolve(false);
                            };
                            probe.src = url;
                        });
                    }

                    // 一次可以选多段：逐段上传，全部传完再刷新详情
                    function uploadVideoFiles(files) {
                        var list = Array.prototype.slice.call(files || []);
                        if (!list.length) {
                            toast('没有选到视频（可能取消了选择）');
                            return;
                        }
                        if (!detailOrder) {
                            toast('请先打开工单详情再上传视频');
                            return;
                        }
                        var exist = (detailOrder.videos || []).length;
                        if (exist >= 3) {
                            toast('最多只能上传 3 段视频，请先删除');
                            return;
                        }
                        var room = 3 - exist;
                        if (list.length > room) {
                            toast('最多还能传 ' + room + ' 段，多选的部分会跳过');
                            list = list.slice(0, room);
                        }
                        var index = 0;
                        var okCount = 0;
                        var failed = 0;
                        showProgress('准备上传…');
                        var next = function () {
                            if (index >= list.length) {
                                hideProgress();
                                if (okCount) { toast('已上传 ' + okCount + ' 段视频'); }
                                if (failed) { toast(failed + ' 段没有传上去，可重试', 6000); }
                                // 不管成没成，都刷新一次：成功的要显示出来，失败的也能看到当前状态
                                openOrder(detailOrder.id);
                                return;
                            }
                            index += 1;
                            var label = '第 ' + index + '/' + list.length + ' 段';
                            setProgress(0, label + ' 上传中…');
                            uploadVideoFile(list[index - 1], label).then(function (ok) {
                                if (ok) { okCount += 1; } else { failed += 1; }
                                next();
                            });
                        };
                        next();
                    }

                    function onVideoPicked(ev) {
                        // 必须先把 FileList 复制成数组，再清空 input：
                        // 有些 WebView 清空 value 会把同一个 FileList 也清掉，
                        // 结果拿到空列表 -> 上传函数直接 return，界面什么都不提示。
                        var files = Array.prototype.slice.call(ev.target.files || []);
                        ev.target.value = '';
                        uploadVideoFiles(files);
                    }
                    document.getElementById('video-input').addEventListener('change', onVideoPicked);
                    document.getElementById('video-record-input').addEventListener('change', onVideoPicked);

                    // ---------------- 位置自动上报（无界面） ----------------
                    // 所有手机端用户（含管理员）打开页面/App 即自动上报，不需要手动点。
                    // 手机只负责把坐标交给服务端；是否在岗由服务端按工作位置判定。
                    // 没有分配工作位置也照常上报（服务端记为「未分配」）。
                    // 网页/PWA 只有前台定位；Android App 由原生前台服务负责，网页 JS 不再重复上报。
                    var LOC = {
                        interval: 60, minDist: 30,
                        watchId: null, lastSent: 0, lastLat: null, lastLng: null,
                        busy: false, retryTimer: null
                    };

                    function locDistance(lat1, lng1, lat2, lng2) {
                        var rad = Math.PI / 180, dLat = (lat2 - lat1) * rad, dLng = (lng2 - lng1) * rad;
                        var a = Math.sin(dLat / 2) * Math.sin(dLat / 2)
                            + Math.cos(lat1 * rad) * Math.cos(lat2 * rad)
                            * Math.sin(dLng / 2) * Math.sin(dLng / 2);
                        return 2 * 6371000 * Math.asin(Math.min(1, Math.sqrt(a)));
                    }
                    function locSend(coords) {
                        if (!coords || LOC.busy) { return; }
                        LOC.busy = true;
                        post('/location', {
                            lat: coords.latitude,
                            lng: coords.longitude,
                            accuracy: coords.accuracy || 0,
                            src: NATIVE ? 'android' : 'pwa'
                        }).then(function (res) {
                            LOC.busy = false;
                            if (!res || !res.ok) { return; }
                            if (res.tracking === false) {
                                if (LOC.watchId !== null) {
                                    navigator.geolocation.clearWatch(LOC.watchId);
                                    LOC.watchId = null;
                                }
                                return;
                            }
                            LOC.lastSent = Date.now();
                            LOC.lastLat = coords.latitude;
                            LOC.lastLng = coords.longitude;
                        }).catch(function () { LOC.busy = false; });
                    }
                    function locOnFix(pos) {
                        var c = pos.coords;
                        var moved = (LOC.lastLat === null) ? Infinity
                            : locDistance(LOC.lastLat, LOC.lastLng, c.latitude, c.longitude);
                        if (LOC.lastLat === null
                            || Date.now() - LOC.lastSent >= LOC.interval * 1000
                            || moved >= LOC.minDist) {
                            locSend(c);
                        }
                    }
                    function locStart() {
                        if (!navigator.geolocation || LOC.watchId !== null) { return; }
                        LOC.watchId = navigator.geolocation.watchPosition(locOnFix, function () { }, {
                            enableHighAccuracy: true, maximumAge: 30000, timeout: 30000
                        });
                    }
                    function locRetry() {
                        if (LOC.retryTimer) { return; }
                        LOC.retryTimer = setTimeout(function () {
                            LOC.retryTimer = null;
                            locInit();
                        }, 60000);
                    }
                    function locInit() {
                        // Android App v1.13+：原生前台服务已经负责定位，网页不要再开一份，
                        // 否则 App 在前台时会出现两条上报。
                        try {
                            if (NATIVE && typeof NATIVE.nativeLocation === 'function'
                                && NATIVE.nativeLocation()) {
                                return;
                            }
                        } catch (e) { }
                        if (!navigator.geolocation || window.isSecureContext === false) { return; }
                        post('/location/state', {}).then(function (res) {
                            if (LOC.retryTimer) {
                                clearTimeout(LOC.retryTimer);
                                LOC.retryTimer = null;
                            }
                            if (!res || !res.ok) { locRetry(); return; }
                            LOC.interval = Math.max(15, Number(res.interval) || 60);
                            LOC.minDist = Math.max(5, Number(res.min_distance) || 30);
                            if (res.tracking === false) { return; }
                            locStart();
                        }).catch(locRetry);
                    }
                    document.addEventListener('visibilitychange', function () {
                        if (document.hidden || LOC.watchId === null) { return; }
                        if (Date.now() - LOC.lastSent < LOC.interval * 1000) { return; }
                        navigator.geolocation.getCurrentPosition(function (pos) {
                            locSend(pos.coords);
                        }, function () { }, {enableHighAccuracy: true, timeout: 20000, maximumAge: 30000});
                    });
                    window.addEventListener('online', function () {
                        if (LOC.watchId === null) { locInit(); return; }
                        if (Date.now() - LOC.lastSent < 60000) { return; }
                        navigator.geolocation.getCurrentPosition(function (pos) {
                            locSend(pos.coords);
                        }, function () { }, {enableHighAccuracy: true, timeout: 20000, maximumAge: 30000});
                    });

                    // 兜底：任何初始化异常都不应阻止页面可用
                    try {
                        updateBadge();
                        loadOrders();
                        flushQueue();
                    } catch (e) {
                        if (window.console) { console.error(e); }
                    }
                    try {
                        locInit();
                    } catch (e) {
                        if (window.console) { console.error(e); }
                    }
                })();
//
